INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-1-1','The lion and the rabbit','Sư tử và thỏ','4000_ESSENTIAL_ENGLISH_WORDS_1_1.mp3',NULL,'00:00:00.000','00:02:11.000','4000-essential-english-words-1',1,1,1) */
	('The lion and the rabbit','Sư tử và thỏ','00:00:00.960','00:00:03.800','4000-essential-english-words-1-1'),
	('A cruel lion lived in the forest','Một con sư tử hung ác sống trong khu rừng','00:00:03.800','00:00:06.900','4000-essential-english-words-1-1'),
	('Every day, he killed and ate a lot of animals','Mỗi ngày, nó giết và ăn thịt rất nhiều loài động vật','00:00:06.900','00:00:11.300','4000-essential-english-words-1-1'),
	('The other animals were afraid the lion would kill them all','Các loài động vật khác sợ rằng sư tử sẽ giết tất cả chúng','00:00:11.300','00:00:16.400','4000-essential-english-words-1-1'),
	('The animals told the lion','Các loài động vật nói với sư tử','00:00:16.400','00:00:18.800','4000-essential-english-words-1-1'),
	('"Let\'s make a deal"','"Chúng ta hãy thỏa thuận đi"','00:00:18.800','00:00:20.400','4000-essential-english-words-1-1'),
	('"If you promise to eat only one animal each day, then one of us will come to you every day"','"Nếu như ngài hứa chỉ ăn một con vật mỗi ngày, thì một trong số chúng tôi sẽ đến gặp ngài mỗi ngày"','00:00:20.400','00:00:27.900','4000-essential-english-words-1-1'),
	('"Then you don\'t have to hunt and kill us"','"Nên là ngài không cần phải đi săn và giết chúng tôi nữa"','00:00:27.900','00:00:31.400','4000-essential-english-words-1-1'),
	('The plan sounded well thought out to the lion, so he agreed, but he also said "If you don\'t come every day, I promise to kill all of you the next day"','Kế hoạch nghe có vẻ tính toán khá ổn với sư tử, nên nó đã đồng ý, nhưng nó cũng nói rằng: "Nếu các người không đến mỗi ngày, ta thề rằng sẽ giết tất cả các ngươi vào ngày hôm sau"','00:00:31.400','00:00:43.800','4000-essential-english-words-1-1'),
	('Each day after that, one animal went to the lion so that the lion could eat it','Mỗi ngày kể từ đó, một con vật lại đến gặp sư tử để cho sư tử có thể ăn thịt','00:00:43.800','00:00:50.000','4000-essential-english-words-1-1'),
	('Then, all the other animals were safe','Thế là, tất cả các loài vật khác đều an toàn','00:00:50.000','00:00:53.400','4000-essential-english-words-1-1'),
	('Finally, it was the rabbit\'s turn to go to the lion','Cuối cùng, đến lượt thỏ đi gặp sư tử','00:00:53.400','00:00:58.000','4000-essential-english-words-1-1'),
	('The rabbit went very slowly that day, so the lion was angry when the rabbit finally arrived','Ngày hôm đó, thỏ đi rất chậm, nên là sư tử rất tức giận khi thỏ cuối cùng cũng đến','00:00:58.000','00:01:05.800','4000-essential-english-words-1-1'),
	('The lion angrily asked the rabbit, "Why are you late?"','Sư tử giận dữ hỏi thỏ: "Tại sao mày đến muộn?"','00:01:05.800','00:01:10.600','4000-essential-english-words-1-1'),
	('"I was hiding from another lion in the forest"','"Tôi đang trốn khỏi một con sư tử khác trong rừng"','00:01:10.600','00:01:14.400','4000-essential-english-words-1-1'),
	('"That lion said he was the king, so I was afraid"','"Con sư tử đó nói nó là vua, vậy nên tôi sợ hãi"','00:01:14.400','00:01:19.000','4000-essential-english-words-1-1'),
	('The lion told the rabbit, "I am the only King here"','Sư tử bảo thỏ: "Ta là vị vua duy nhất ở đây"','00:01:19.100','00:01:23.700','4000-essential-english-words-1-1'),
	('"Take me to that other lion, and I will kill him"','Hãy dẫn ta đến chỗ con sư tử kia, và ta sẽ giết nó','00:01:23.700','00:01:28.000','4000-essential-english-words-1-1'),
	('The rabbit replied, "I will be happy to show you where he lives"','Thỏ đáp lại: "Tôi rất vui cho ngài biết nơi hắn ta sống"','00:01:28.000','00:01:33.200','4000-essential-english-words-1-1'),
	('The rabbit led the lion to an old well in the middle of the forest','Thỏ dẫn sư tử đến một cái giếng cũ ở giữa khu rừng','00:01:33.200','00:01:38.300','4000-essential-english-words-1-1'),
	('The well was very deep with water at the bottom','Cái giếng rất sâu và có nước ở đáy','00:01:38.300','00:01:42.000','4000-essential-english-words-1-1'),
	('The rabbit told the lion, "Look in there"','Thỏ bảo sư tử: "Ngài hãy nhìn vào đây"','00:01:42.000','00:01:45.200','4000-essential-english-words-1-1'),
	('"The lion lives at the bottom"','Con sư tử đó sống ở dưới đáy','00:01:45.200','00:01:47.600','4000-essential-english-words-1-1'),
	('When the lion looked in the well, he could see his own face in the water','Khi sư tử nhìn vào giếng, nó có thể thấy khuôn mặt của chính mình trong nước','00:01:47.600','00:01:53.400','4000-essential-english-words-1-1'),
	('He thought that was the other lion','Nó tưởng đó là con sư tử kia','00:01:53.400','00:01:56.200','4000-essential-english-words-1-1'),
	('Without waiting another moment, the lion jumped into the well to attack the other lion','Không chờ đợi thêm giây phút nào khác nữa, sư tử nhảy xuống giếng để tấn công con sư tử kia','00:01:56.200','00:02:02.500','4000-essential-english-words-1-1'),
	('He never came out','Nó không bao giờ thoát ra được nữa','00:02:02.500','00:02:04.500','4000-essential-english-words-1-1'),
	('All of the other animals in the forest were very pleased with their rabbit\'s clever trick','Tất cả các loài vật khác trong rừng đều rất hài lòng với mưu kế thông minh của thỏ','00:02:04.500','00:02:11.000','4000-essential-english-words-1-1'),

	/* (UUID(),'4000-essential-english-words-1-2','The laboratory','Phòng thí nghiệm','4000_ESSENTIAL_ENGLISH_WORDS_1_2.mp3',NULL,'00:00:00.000','00:02:13.800','4000-essential-english-words-1',1,1,2) */
	('The laboratory','Phòng thí nghiệm','00:00:00.960','00:00:03.000','4000-essential-english-words-1-2'),
	('Mia\'s father had a laboratory, but she had no idea what was in it','Bố của Mia có một phòng thí nghiệm, nhưng cô bé không biết có thứ gì bên trong đó','00:00:03.000','00:00:08.600','4000-essential-english-words-1-2'),
	('Her dad always closed and locked the door when he went in','Bố cô ấy luôn đóng và khóa cửa khi ông đi vào','00:00:08.600','00:00:13.000','4000-essential-english-words-1-2'),
	('She knew that he used it to do projects for work','Cô bé biết rằng ông dùng nó để làm các dự án dành cho công việc','00:00:13.000','00:00:16.400','4000-essential-english-words-1-2'),
	('He never told Mia what these projects were','Ông chưa bao giờ nói cho Mia biết những dự án đó là gì','00:00:16.400','00:00:20.400','4000-essential-english-words-1-2'),
	('One night, Mia approached the door to the laboratory','Một đêm nọ, Mia tiến đến gần cửa phòng thí nghiệm','00:00:20.400','00:00:24.800','4000-essential-english-words-1-2'),
	('She stopped and thought, "I wonder what crazy experiment he is doing now?"','Cô bé dừng lại và nghĩ, "Mình thắc mắc là bố đang làm thí nghiệm điên rồ gì bây giờ nhỉ?"','00:00:24.800','00:00:30.200','4000-essential-english-words-1-2'),
	('Suddenly, she heard a loud noise','Bỗng nhiên, cô bé nghe thấy một tiếng động lớn','00:00:30.200','00:00:33.000','4000-essential-english-words-1-2'),
	('It sounded like an evil laugh','Nghe như là một tiếng cười nham hiểm','00:00:33.000','00:00:35.800','4000-essential-english-words-1-2'),
	('The noise scared her, so she walked quickly back to her room','Tiếng động làm cô bé hoảng sợ, vậy là cô bé bước nhanh về phòng của mình','00:00:35.800','00:00:40.600','4000-essential-english-words-1-2'),
	('The next night, her friend Liz came to her house','Đêm hôm sau, bạn của cô bé, Liz, đến nhà cô','00:00:40.600','00:00:44.300','4000-essential-english-words-1-2'),
	('When Liz arrived, Mia told her about the night before','Khi Liz tới, Mia kể cho cô bé nghe về chuyện tối hôm trước','00:00:44.300','00:00:48.300','4000-essential-english-words-1-2'),
	('"Oh, it was terrible," she said','"Ôi, thật kinh khủng," cô bé nói','00:00:48.300','00:00:52.000','4000-essential-english-words-1-2'),
	('"Why don\'t we see what is in there?" Liz asked','"Sao chúng ta không vào xem trong đó có gì nhỉ?" Liz hỏi','00:00:52.000','00:00:56.000','4000-essential-english-words-1-2'),
	('"It will be a fun adventure"',' "Đó sẽ là một cuộc phiêu lưu thú vị"','00:00:56.000','00:00:58.700','4000-essential-english-words-1-2'),
	('Mia felt nervous about going into her father\'s laboratory, but she agreed','Mia cảm thấy lo lắng khi bước vào phòng thí nghiệm của cha mình, nhưng rồi cô bé đã đồng ý','00:00:58.700','00:01:04.000','4000-essential-english-words-1-2'),
	('As always, the door was locked','Như mọi khi, cửa đã bị khóa','00:01:04.000','00:01:06.600','4000-essential-english-words-1-2'),
	('They waited until Mia\'s father left the laboratory to eat dinner','Hai người đợi tới khi cha của Mia rời khỏi phòng thí nghiệm để ăn tối','00:01:06.600','00:01:10.800','4000-essential-english-words-1-2'),
	('"He didn\'t lock the door" Liz said',' "Ông ấy không khóa cửa kìa" Liz nói','00:01:10.800','00:01:13.900','4000-essential-english-words-1-2'),
	('"Let\'s go"','"Đi nào"','00:01:13.900','00:01:15.300','4000-essential-english-words-1-2'),
	('The laboratory was dark','Phòng thí nghiệm thì tối om','00:01:15.300','00:01:17.600','4000-essential-english-words-1-2'),
	('The girls walked down the stairs carefully',' Hai cô bé bước xuống cầu thang một cách cẩn thận','00:01:17.600','00:01:20.800','4000-essential-english-words-1-2'),
	('Mia smelled strange chemicals','Mia ngửi thấy mùi hóa chất lạ','00:01:20.800','00:01:23.400','4000-essential-english-words-1-2'),
	('What terrible thing was her father creating?','Có thứ gì đó rất khủng khiếp mà bố cô ấy đang tạo ra?','00:01:23.400','00:01:26.800','4000-essential-english-words-1-2'),
	('Suddenly, they heard an evil laugh','Bất chợt, họ nghe thấy tiếng cười độc ác','00:01:26.800','00:01:30.200','4000-essential-english-words-1-2'),
	('It was even worse than the one Mia heard the night before','Thậm chí còn tệ hơn cả tiếng cười mà Mia nghe thấy đêm hôm trước','00:01:30.200','00:01:34.000','4000-essential-english-words-1-2'),
	('What if a monster was going to kill them?','Nếu như một con quái vật sắp giết họ thì sao nhỉ?','00:01:34.000','00:01:37.200','4000-essential-english-words-1-2'),
	('Mia had to do something','Mia buộc phải làm gì đó','00:01:37.200','00:01:39.000','4000-essential-english-words-1-2'),
	('She shouted for help','Cô bé hét lên cầu cứu','00:01:39.000','00:01:40.800','4000-essential-english-words-1-2'),
	('Mia\'s father ran into the room and turned on the lights','Cha của Mia chạy vào phòng và bật đèn','00:01:40.800','00:01:44.100','4000-essential-english-words-1-2'),
	('"Oh, no," he said','"Ôi, không," ông ấy nói','00:01:44.100','00:01:46.600','4000-essential-english-words-1-2'),
	('"You must have learned my secret"','Con hẳn là đã biết bí mật của bố rồi','00:01:46.600','00:01:49.400','4000-essential-english-words-1-2'),
	('"Your monster tried to kill us," Mia said','"Con quái vật của bố đã cố giết chúng ta," Mia nói','00:01:49.400','00:01:52.900','4000-essential-english-words-1-2'),
	('"Monster?" he asked',' "Quái vật nào? ông ấy hỏi','00:01:53.040','00:01:55.500','4000-essential-english-words-1-2'),
	('"You mean this?"','"Ý con là gì?"','00:01:55.500','00:01:57.300','4000-essential-english-words-1-2'),
	('He had a pretty doll in his hands','Ông có một con búp bê xinh đẹp trong tay','00:01:57.300','00:02:00.000','4000-essential-english-words-1-2'),
	('The doll laughed','Con búp bê cười','00:02:00.000','00:02:01.400','4000-essential-english-words-1-2'),
	('The laugh didn\'t sound so evil anymore','Tiếng cười nghe không còn độc ác nữa','00:02:01.400','00:02:04.800','4000-essential-english-words-1-2'),
	('"I made this for your birthday"','"Bố làm cái này cho sinh nhật con"','00:02:04.800','00:02:07.300','4000-essential-english-words-1-2'),
	('"I wanted to give it to you then, but you can have it now"','"Bố muốn tặng nó cho con sau, nhưng con có thể nhận nó ngay bây giờ"','00:02:07.300','00:02:11.360','4000-essential-english-words-1-2'),
	('"I hope you like it"','"Bố hi vọng con thích nó"','00:02:11.360','00:02:13.800','4000-essential-english-words-1-2'),

	/* (UUID(),'4000-essential-english-words-1-3','The report','Báo cáo','4000_ESSENTIAL_ENGLISH_WORDS_1_3.mp3',NULL,'00:00:00.000','00:02:11.000','4000-essential-english-words-1',1,1,3) */
	('The report','Báo cáo','00:00:00.960','00:00:02.800','4000-essential-english-words-1-3'),
	('Lee sat among the books at the library and thought about his group project','Lee ngồi giữa những cuốn sách trong thư viện và nghĩ về dự án của nhóm mình','00:00:02.800','00:00:08.700','4000-essential-english-words-1-3'),
	('They had to turn it in soon, but he hadn\'t even started his part','Họ phải nộp sớm, nhưng cậu ta thậm chí còn chưa bắt đầu phần của mình','00:00:08.700','00:00:13.700','4000-essential-english-words-1-3'),
	('Jack and Claire were in his group','Jack và Claire ở trong nhóm của cậu','00:00:13.700','00:00:16.900','4000-essential-english-words-1-3'),
	('They had worked hard','Họ đã làm việc rất chăm chỉ','00:00:16.900','00:00:18.500','4000-essential-english-words-1-3'),
	('They were also very smart and Lee didn\'t want them to get a bad grade','Họ cũng rất thông minh và Lee không muốn họ bị điểm kém','00:00:18.500','00:00:24.000','4000-essential-english-words-1-3'),
	('Jack did the report','Jack đã làm báo cáo','00:00:24.000','00:00:25.900','4000-essential-english-words-1-3'),
	('He wrote a lot of very good sentences and described things with great adjectives','Cậu ấy đã viết nhiều câu từ rất hay và miêu tả mọi thứ với những tính từ tuyệt vời','00:00:25.900','00:00:32.000','4000-essential-english-words-1-3'),
	('Claire drew a nice map of the stars','Claire thì vẽ một bản đồ với những ngôi sao rất đẹp','00:00:32.000','00:00:35.000','4000-essential-english-words-1-3'),
	('Now, Lee needed to do his part of the project','Bây giờ, Lee cần hoàn thành phần dự án của mình','00:00:35.000','00:00:38.700','4000-essential-english-words-1-3'),
	('"Well, I suppose I need to start my model," Lee thought','"Chà, tôi cho là mình cần phải bắt đầu mô hình của mình," Lee nghĩ','00:00:38.700','00:00:43.400','4000-essential-english-words-1-3'),
	('Making a model of a planet was really hard','Làm mô hình một hành tinh thật sự rất khó','00:00:43.400','00:00:47.000','4000-essential-english-words-1-3'),
	('Lee tried to read several books, but he couldn\'t comprehend any of the charts','Lee đã cố gắng đọc một vài cuốn sách, nhưng cậu ấy không thể hiểu bất kỳ một biểu đồ nào','00:00:47.000','00:00:53.000','4000-essential-english-words-1-3'),
	('"We\'re going to fail because of me" Lee said','"Chúng ta sẽ thất bại vì mình mất thôi" Lee nói','00:00:53.000','00:00:57.500','4000-essential-english-words-1-3'),
	('He put his head down on the table and said, "I wish I could see a planet, instead of having to read about it"','Cậu ấy gục đầu xuống bàn và nói, "Ước gì mình có thể nhìn thấy một hành tinh, thay vì phải đọc về nó"','00:00:57.500','00:01:05.800','4000-essential-english-words-1-3'),
	('Suddenly, there was a bright light','Đột nhiên, có một ánh sáng chói lòa','00:01:05.800','00:01:09.000','4000-essential-english-words-1-3'),
	('Lee was pulled from his chair, through the roof, and right into a strange ship','Lee bị kéo khỏi ghế, xuyên qua mái nhà, và chạm ngay vào một con tàu kỳ lạ','00:01:09.000','00:01:15.500','4000-essential-english-words-1-3'),
	('"Hello, kid," said an alien','"Xin chào, nhóc," một người ngoài hành tinh nói','00:01:15.500','00:01:18.000','4000-essential-english-words-1-3'),
	('"Did you ask for help?"','"Cậu cần giúp đỡ có phải không?"','00:01:18.000','00:01:19.800','4000-essential-english-words-1-3'),
	('Lee told the friendly alien all about his project','Lee kể cho người ngoài hành tinh thân thiện tất cả về dự án của mình','00:01:19.900','00:01:24.500','4000-essential-english-words-1-3'),
	('The alien agreed to help Lee solve his problem','Người ngoài hành tinh đồng ý giúp Lee giải quyết vấn đề của cậu ta','00:01:24.500','00:01:28.000','4000-essential-english-words-1-3'),
	('"First, we\'ll fly through space to view the universe"',' "Đầu tiên, chúng ta sẽ bay qua không gian để ngắm nhìn vũ trụ"','00:01:28.000','00:01:31.760','4000-essential-english-words-1-3'),
	('"Then, I can help you make a model of my planet"','"Sau đó, tôi có thể giúp cậu làm mô hình hành tinh của tôi"','00:01:31.830','00:01:35.700','4000-essential-english-words-1-3'),
	('Soon, they were going through the clouds','"Chẳng mấy chốc, họ đã đi qua những đám mây"','00:01:35.700','00:01:38.700','4000-essential-english-words-1-3'),
	('They passed the moon','Họ đã đi qua mặt trăng','00:01:38.700','00:01:40.210','4000-essential-english-words-1-3'),
	('Then they viewed Mars','Sau đó, họ đã ngắm nhìn sao Hỏa','00:01:40.270','00:01:42.300','4000-essential-english-words-1-3'),
	('Lee was very excited','Lee rất háo hức','00:01:42.400','00:01:44.700','4000-essential-english-words-1-3'),
	('Instead of a bad grade, his group would have the best project ever','Thay vì nhận điểm kém, nhóm của cậu ấy sẽ có dự án tốt nhất từ trước đến nay','00:01:44.700','00:01:49.900','4000-essential-english-words-1-3'),
	('"It\'s time to go home, the alien finally said','"Đã đến lúc về nhà rồi," người ngoài hành tinh cuối cùng cũng nói','00:01:49.900','00:01:54.020','4000-essential-english-words-1-3'),
	('On the way back, he helped Lee make a model of the planet Mars','Trên đường về, cậu ấy đã giúp Lee làm một mô hình hành tinh Sao Hỏa','00:01:54.020','00:01:59.500','4000-essential-english-words-1-3'),
	('Soon, they were on Earth','Chẳng mấy chốc, họ đã ở trên Trái Đất','00:01:59.500','00:02:02.000','4000-essential-english-words-1-3'),
	('"Thanks," Lee said','"Cảm ơn," Lee nói','00:02:02.000','00:02:03.600','4000-essential-english-words-1-3'),
	('"My model will be awesome"','"Mô hình của tôi sẽ tuyệt vời"','00:02:03.670','00:02:06.000','4000-essential-english-words-1-3'),
	('Then he took his model and said goodbye to his new friend','Sau đó, cậu ấy lấy mô hình của mình và nói lời tạm biệt với người bạn mới','00:02:06.000','00:02:11.000','4000-essential-english-words-1-3'),

	/* (UUID(),'4000-essential-english-words-1-4','The dog\'s bell','Chiếc chuông của chú chó','4000_ESSENTIAL_ENGLISH_WORDS_1_4.mp3',NULL,'00:00:00.000','00:02:03.000','4000-essential-english-words-1',1,1,4) */
	('The dog\'s bell','Chiếc chuông của chú chó','00:00:00.960','00:00:03.000','4000-essential-english-words-1-4'),
	('John\'s dog was a bad dog','Chó của John là một con chó tồi tệ','00:00:03.000','00:00:06.000','4000-essential-english-words-1-4'),
	('He bit people frequently','Nó thường xuyên cắn người','00:00:06.000','00:00:08.500','4000-essential-english-words-1-4'),
	('John had great concern about this','John rất lo lắng về điều này','00:00:08.500','00:00:11.100','4000-essential-english-words-1-4'),
	('It was not an appropriate way for a dog to behave','Đây không phải là cách cư xử thích hợp cho một chú chó','00:00:11.100','00:00:14.700','4000-essential-english-words-1-4'),
	('His friends in the village always expected the dog to bite them','Bạn bè trong làng của anh luôn đoán trước được con chó sẽ cắn họ','00:00:14.700','00:00:19.400','4000-essential-english-words-1-4'),
	('The news about John\'s dog spread through the village','Tin tức về con chó của Jon lan truyền khắp làng','00:00:19.400','00:00:22.900','4000-essential-english-words-1-4'),
	('None of the people wanted to go to John\'s house','Không ai muốn đến nhà John','00:00:22.900','00:00:26.300','4000-essential-english-words-1-4'),
	('John tried to instruct the dog to behave, but it never worked','John đã cố gắng hướng dẫn cho con chó cách cư xử, nhưng nó chưa bao giờ hiệu quả','00:00:26.300','00:00:30.800','4000-essential-english-words-1-4'),
	('He tried to be patient and teach the dog to be calm','Anh cố gắng kiên nhẫn và dạy con chó bình tĩnh','00:00:30.800','00:00:35.000','4000-essential-english-words-1-4'),
	('That also didn\'t work','Cách đó cũng không hiệu quả','00:00:35.000','00:00:37.100','4000-essential-english-words-1-4'),
	('John didn\'t want to punish the dog','John không muốn trừng phạt con chó','00:00:37.100','00:00:40.000','4000-essential-english-words-1-4'),
	('"How will I stop my dog\'s bad habit?" John asked himself','"Làm cách nào để tôi ngăn chặn thói quen xấu của con chó?" John tự hỏi bản thân','00:00:40.000','00:00:45.200','4000-essential-english-words-1-4'),
	('John\'s friend came to talk to him about the issue','Bạn của John đến để nói chuyện với anh ấy về vấn đề này','00:00:45.200','00:00:48.900','4000-essential-english-words-1-4'),
	('During their important meeting, his friend said, "The people in the village asked me to represent them"','Trong cuộc họp quan trọng của họ, người bạn của anh ấy nói, "Người dân trong làng đã yêu cầu mình đại diện cho họ"','00:00:48.900','00:00:55.400','4000-essential-english-words-1-4'),
	('"We want your dog to stop this habit"','"Chúng tôi muốn con chó của cậu dừng ngay thói quen này lại"','00:00:55.400','00:00:58.100','4000-essential-english-words-1-4'),
	('"Why don\'t you put a bell around the dog\'s neck?"','"Tại sao cậu không đeo một chiếc chuông quanh cổ con chó?"','00:00:58.100','00:01:01.000','4000-essential-english-words-1-4'),
	('"This way, we would hear your dog coming down the street"','"Với cách này, chúng ta sẽ nghe thấy tiếng con chó của cậu đang đi xuống phố','00:01:01.000','00:01:04.800','4000-essential-english-words-1-4'),
	('John thought this was a great idea','John nghĩ rằng đây quả là một ý kiến tuyệt vời','00:01:04.800','00:01:07.600','4000-essential-english-words-1-4'),
	('Now people could stay away from the dog, it would not be able to bite anyone anymore','Giờ thì mọi người có thể tránh xa con chó, nó sẽ không thể cắn ai nữa','00:01:07.600','00:01:14.000','4000-essential-english-words-1-4'),
	('The dog liked the bell, too','Con chó cũng thích cái chuông','00:01:14.000','00:01:16.000','4000-essential-english-words-1-4'),
	('People looked at him when they heard his bell','Mọi người nhìn nó khi họ nghe thấy tiếng chuông','00:01:16.000','00:01:19.500','4000-essential-english-words-1-4'),
	('This made the dog very content','Điều này khiến con chó rất hài lòng','00:01:19.500','00:01:21.700','4000-essential-english-words-1-4'),
	('He liked the song the bell played when he walked','Nó thích bài hát mà tiếng chuông bắt đầu vang lên khi nó bước đi','00:01:21.700','00:01:25.000','4000-essential-english-words-1-4'),
	('One day John\'s dog strolled through the village and met some other dogs','Một ngày nọ, con chó của John đi dạo qua làng và gặp những con chó khác','00:01:25.000','00:01:30.000','4000-essential-english-words-1-4'),
	('He expected them to want a bell like his','Nó mong đợi bọn chúng sẽ muốn một cái chuông y như của nó','00:01:30.000','00:01:32.800','4000-essential-english-words-1-4'),
	('But they laughed at his bell','Nhưng bọn chúng cười nhạo cái chuông của nó','00:01:32.800','00:01:35.000','4000-essential-english-words-1-4'),
	('They said the bell made people avoid him','Chúng nói rằng chiếc chuông khiến cho mọi người tránh xa nó','00:01:35.000','00:01:37.900','4000-essential-english-words-1-4'),
	('John\'s dog shook his head','Con chó của John lắc đầu','00:01:37.900','00:01:40.000','4000-essential-english-words-1-4'),
	('"No, they look at me because they like the bell"','Không, họ nhìn tôi vì họ thích chiếc chuông này','00:01:40.000','00:01:43.900','4000-essential-english-words-1-4'),
	('The other dogs said, "You have the wrong idea of what makes you popular"','Những con chó khác nói: "Mày hiểu nhầm về điều đã khiến mày nổi tiếng rồi đấy"','00:01:43.900','00:01:49.000','4000-essential-english-words-1-4'),
	('"Of course they like your bell"','Tất nhiên là họ thích cái chuông của mày','00:01:49.000','00:01:51.000','4000-essential-english-words-1-4'),
	('"It tells them where you are so they can avoid you"','Nó báo cho họ biết mày đang ở đâu thế là họ có thể tránh xa mày','00:01:51.000','00:01:54.000','4000-essential-english-words-1-4'),
	('"You aren\'t able to bite them anymore"','"Mày không thể cắn họ nữa"','00:01:54.000','00:01:57.000','4000-essential-english-words-1-4'),
	('You see, being popular isn\'t something positive when it\'s for the wrong reason','Mày thấy đấy, nổi tiếng không phải là điều gì tích cực khi nó xuất phát từ lý do sai lầm','00:01:57.000','00:02:03.000','4000-essential-english-words-1-4'),

	/* (UUID(),'4000-essential-english-words-1-5','The jackal and the sun child','Chú chó rừng và đứa con Mặt trời','4000_ESSENTIAL_ENGLISH_WORDS_1_5.mp3',NULL,'00:00:00.000','00:02:11.600','4000-essential-english-words-1',1,1,5) */
	('The Jackal and the Sun Child','Chú chó rừng và đứa con Mặt trời','00:00:00.960','00:00:04.000','4000-essential-english-words-1-5'),
	('A jackal is a wild dog with a big black back','Chó rừng là một loài chó hoang dã với cái lưng đen to lớn','00:00:04.000','00:00:08.600','4000-essential-english-words-1-5'),
	('It resides in the desert','Nó sinh sống ở sa mạc','00:00:08.600','00:00:10.600','4000-essential-english-words-1-5'),
	('But how did the jackal get his black back?','Nhưng làm thế nào mà chó rừng có cái lưng đen vậy?','00:00:10.650','00:00:14.600','4000-essential-english-words-1-5'),
	('This was how it happened','Đây là cách mọi chuyện đã xảy ra','00:00:14.600','00:00:17.000','4000-essential-english-words-1-5'),
	('One day, the jackal saw a girl','Một ngày nọ, chó rừng nhìn thấy một cô bé','00:00:17.000','00:00:20.300','4000-essential-english-words-1-5'),
	('She was sitting upon a rock','Cô bé đang ngồi trên một tảng đá','00:00:20.300','00:00:22.300','4000-essential-english-words-1-5'),
	('She was not a normal child','Cô bé không phải là một đứa trẻ bình thường','00:00:22.380','00:00:24.800','4000-essential-english-words-1-5'),
	('She was a rare and beautiful sun child','Cô bé là một đứa trẻ mặt trời hiếm có và xinh đẹp','00:00:24.850','00:00:28.300','4000-essential-english-words-1-5'),
	('She was bright and warm like the sun','Cô bé tỏa sáng và ấm áp như mặt trời','00:00:28.300','00:00:31.500','4000-essential-english-words-1-5'),
	('The child saw the jackal and smiled','Đứa trẻ thấy chó rừng và mỉm cười','00:00:31.700','00:00:34.620','4000-essential-english-words-1-5'),
	('She said, "Jackal, I have been relaxing on this rock for too long"','Cô bé nói: "Chó rừng ơi, tôi đã thư giãn trên phiến đá này quá lâu rồi"','00:00:34.650','00:00:40.700','4000-essential-english-words-1-5'),
	('"I must get home soon"','"Tôi phải về nhà sớm thôi"','00:00:40.700','00:00:42.900','4000-essential-english-words-1-5'),
	('"But, I am slow and you are fast"','"Nhưng, tôi thì chậm chạp còn bạn lại nhanh nhẹn"','00:00:43.000','00:00:46.020','4000-essential-english-words-1-5'),
	('"You will likely get me home more quickly"','"Bạn sẽ có thể đưa tôi về nhà nhanh hơn nhiều"','00:00:46.300','00:00:49.700','4000-essential-english-words-1-5'),
	('Then she requested, "Will you carry me home?"','"Rồi cô bé đề nghị: "Bạn sẽ đưa tôi về nhà chứ?"','00:00:49.830','00:00:53.410','4000-essential-english-words-1-5'),
	('If you do, I\'ll give you a gift','"Nếu bạn làm được, tôi sẽ tặng bạn một món quà"','00:00:53.600','00:00:56.450','4000-essential-english-words-1-5'),
	('"This necklace belongs to me, but I will give it to you"','"Chiếc vòng cổ này là của tôi, nhưng tôi sẽ đưa nó cho bạn"','00:00:56.600','00:01:01.600','4000-essential-english-words-1-5'),
	('The wild jackal agreed','"Chó rừng hoang dã đồng ý"','00:01:01.600','00:01:03.800','4000-essential-english-words-1-5'),
	('So the sun child sat on the dog\'s back','"Vậy là đứa bé mặt trời ngồi lên lưng chú chó"','00:01:03.800','00:01:07.300','4000-essential-english-words-1-5'),
	('They started to walk','Họ bắt đầu đi dạo','00:01:07.300','00:01:08.700','4000-essential-english-words-1-5'),
	('But soon, the jackal felt ill','Nhưng không lâu sau, chó rừng cảm thấy không khỏe','00:01:08.800','00:01:11.200','4000-essential-english-words-1-5'),
	('The sun child was very hot on his back','Đứa trẻ mặt trời ngày càng vô cùng nóng ở trên lưng nó','00:01:11.240','00:01:14.780','4000-essential-english-words-1-5'),
	('The heat was hurting his back very badly','Sức nóng đã làm tổn thương chiếc lưng của nó rất tồi tệ','00:01:14.780','00:01:18.000','4000-essential-english-words-1-5'),
	('"I made a terrible error in judgment" he thought','"Tôi đã mắc một lỗi sai khủng khiếp trong việc phán đoán" nó nghĩ','00:01:18.000','00:01:23.000','4000-essential-english-words-1-5'),
	('He shouldn\'t have agreed to carry her','Nó không nên đồng ý trở cô','00:01:23.000','00:01:25.330','4000-essential-english-words-1-5'),
	('So he asked her to get off','Thế là nó yêu cầu cô bước xuống','00:01:25.350','00:01:27.800','4000-essential-english-words-1-5'),
	('But she did not','Nhưng cô bé đã không làm thế','00:01:27.800','00:01:29.500','4000-essential-english-words-1-5'),
	('The jackal\'s back continued to get hotter and hotter','Lưng của chó rừng tiếp tục ngày càng nóng hơn','00:01:29.500','00:01:32.800','4000-essential-english-words-1-5'),
	('He had to get away from the sun child','Nó phải tránh xa khỏi đứa trẻ mặt trời','00:01:32.800','00:01:35.800','4000-essential-english-words-1-5'),
	('So he made a plan','Thế là nó đưa ra một kế hoạch','00:01:35.800','00:01:37.700','4000-essential-english-words-1-5'),
	('First, he ran as fast as he could','Đầu tiên, nó chạy nhanh nhất có thể','00:01:37.700','00:01:40.210','4000-essential-english-words-1-5'),
	('He hoped the sun child would fall off','Nó hy vọng đứa trẻ mặt trời sẽ ngã xuống','00:01:40.270','00:01:42.830','4000-essential-english-words-1-5'),
	('But she did not','Nhưng cô bé không ngã','00:01:42.970','00:01:44.400','4000-essential-english-words-1-5'),
	('So when the sun child was looking at the sky, not aware of the jackal\'s next plan, he jumped into a field of flowers','Thế là khi đứa trẻ mặt trời ngước nhìn lên trời, không nhận thức được kế hoạch tiếp theo của chó rừng, nó đã nhảy vào một cánh đồng hoa','00:01:44.450','00:01:53.300','4000-essential-english-words-1-5'),
	('As a result, the child rolled off his back','Kết quả là, đứa trẻ đã lăn xuống khỏi lưng nó','00:01:53.300','00:01:56.600','4000-essential-english-words-1-5'),
	('The jackal ran away','Chó rừng bỏ chạy','00:01:56.600','00:01:58.800','4000-essential-english-words-1-5'),
	('But the sun child left a mark on the jackal\'s back, a visible black mark','Nhưng đứa trẻ mặt trời đã để lại một dấu vết trên lưng của chó rừng, một vết đen luôn hiện hữu','00:01:58.800','00:02:04.900','4000-essential-english-words-1-5'),
	('Ever since his experience with the sun child, the jackal has had a black back','Kể từ lúc trải nghiệm với đứa trẻ mặt trời, chó rừng đã có chiếc lưng màu đen','00:02:04.950','00:02:11.600','4000-essential-english-words-1-5');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-1-6','The friendly ghost','Hồn ma thân thiện','4000_ESSENTIAL_ENGLISH_WORDS_1_6.mp3',NULL,'00:00:00.000','00:02:11.300','4000-essential-english-words-1',1,1,6) */
	('The friendly ghost','Hồn ma thân thiện','00:00:00.960','00:00:03.000','4000-essential-english-words-1-6'),
	('A nice woman lived by a large river','Có một người phụ nữ tốt bụng sống bên cạnh một con sông lớn','00:00:03.000','00:00:06.600','4000-essential-english-words-1-6'),
	('She loved children','Bà rất yêu trẻ con','00:00:06.600','00:00:08.800','4000-essential-english-words-1-6'),
	('She wanted to help them in any way','Bà luôn mong muốn giúp đỡ chúng bằng bất cứ cách nào','00:00:08.800','00:00:11.800','4000-essential-english-words-1-6'),
	('She loved her community, and everyone in the community loved her','Bà yêu thương cộng đồng của mình, và tất cả mọi người trong cộng đồng đều yêu quý bà','00:00:11.800','00:00:16.800','4000-essential-english-words-1-6'),
	('She lived a very long time and became very wise','Bà đã sống ở đây rất lâu rồi và đã trở nên vô cùng thông thái','00:00:16.800','00:00:21.800','4000-essential-english-words-1-6'),
	('When she died, she became a ghost','Khi bà mất, bà trở thành một hồn ma','00:00:21.800','00:00:24.800','4000-essential-english-words-1-6'),
	('She was dead, but every night she returned to her community','Bà đã mất rồi, nhưng hằng đêm bà vẫn quay lại cộng đồng của mình','00:00:24.800','00:00:29.800','4000-essential-english-words-1-6'),
	('She wanted to help children and not to cause them fright','Bà ấy mong muốn giúp đỡ lũ trẻ chứ không muốn khiến chúng sợ','00:00:29.800','00:00:33.600','4000-essential-english-words-1-6'),
	('But she had a scary voice','Nhưng bà có một giọng nói rất rùng rợn','00:00:33.600','00:00:36.000','4000-essential-english-words-1-6'),
	('Children were afraid of her, but the ghost was a good one','Lũ trẻ rất sợ bà, nhưng bà là một hồn ma tốt','00:00:36.000','00:00:40.400','4000-essential-english-words-1-6'),
	('She only scared them to help them','Bà ấy chỉ doạ chúng để muốn giúp chúng mà thôi','00:00:40.400','00:00:43.200','4000-essential-english-words-1-6'),
	('One night, some children and a dog were playing by the river','Một đêm, vài đứa trẻ và một chú chó đang đùa nghịch gần bờ sông','00:00:43.200','00:00:47.800','4000-essential-english-words-1-6'),
	('They were having fun with their pet','Chúng đang vui vẻ với thú cưng','00:00:47.800','00:00:50.000','4000-essential-english-words-1-6'),
	('But they were far from home','Nhưng chúng ở khá xa nhà','00:00:50.000','00:00:52.800','4000-essential-english-words-1-6'),
	('Then the weather became bad','Cùng lúc đó thời tiết bỗng trở nên tồi tệ','00:00:52.800','00:00:55.000','4000-essential-english-words-1-6'),
	('It rained and rained','Trời ngày càng mưa','00:00:55.000','00:00:57.600','4000-essential-english-words-1-6'),
	('The river was rising','Nước sông đang dần dâng lên','00:00:57.600','00:00:59.800','4000-essential-english-words-1-6'),
	('It was very dark','Trời thì vô cùng tối','00:00:59.800','00:01:01.600','4000-essential-english-words-1-6'),
	('The children knew they were lost','Lũ trẻ nhận ra rằng chúng đã bị lạc','00:01:01.600','00:01:04.000','4000-essential-english-words-1-6'),
	('They needed to go north, but they didn\'t know which direction it was','Chúng cần phải đi về hướng Bắc, nhưng chúng không biết hướng Bắc ở đâu','00:01:04.000','00:01:09.000','4000-essential-english-words-1-6'),
	('When the moon came out, they saw a ghost by the river','Khi Mặt trăng xuất hiện, chúng nhìn thấy một hồn ma ở dòng sông','00:01:09.000','00:01:13.200','4000-essential-english-words-1-6'),
	('The ghost said, "Go away"','Hồn ma quát: "Cút ngay"','00:01:13.200','00:01:16.700','4000-essential-english-words-1-6'),
	('The children felt great fright','Lũ trẻ cảm thấy vô cùng sợ hãi','00:01:16.700','00:01:19.500','4000-essential-english-words-1-6'),
	('They knew it was a ghost','Chúng biết đó là một hồn ma','00:01:19.500','00:01:21.600','4000-essential-english-words-1-6'),
	('Then the ghost moved closer','Rồi hồn ma tiến lại gần chúng','00:01:21.600','00:01:23.700','4000-essential-english-words-1-6'),
	('She yelled again, "Go away"','Hồn ma lại quát lên lần nữa: "Cút ngay"','00:01:23.700','00:01:27.800','4000-essential-english-words-1-6'),
	('The children became very upset','Lũ trẻ trở nên rất buồn bã','00:01:27.800','00:01:30.200','4000-essential-english-words-1-6'),
	('Some of them began to cry','Vài đứa bắt đầu khóc','00:01:30.200','00:01:32.500','4000-essential-english-words-1-6'),
	('The children knew they had a choice: they could escape, or they could stay and face this scary individual in the dark','Lũ trẻ biết chúng chỉ có một lựa chọn: Chúng có thế chạy trốn, hoặc chúng có thể ở lại và đối mặt với cái cá thể đáng sợ trong bóng tối kia','00:01:32.500','00:01:39.800','4000-essential-english-words-1-6'),
	('The children ran a long distance away','Lũ trẻ chạy đi một quãng rất xa','00:01:39.900','00:01:43.500','4000-essential-english-words-1-6'),
	('The ghost followed them all the way','Hồn ma đi theo chúng trên suốt chặng đường','00:01:43.500','00:01:46.000','4000-essential-english-words-1-6'),
	('Finally, the children reached home','Cuối cùng, lũ trẻ đã về tới nhà','00:01:46.000','00:01:48.800','4000-essential-english-words-1-6'),
	('The ghost was very happy','Hồn ma thấy rất vui','00:01:48.800','00:01:50.800','4000-essential-english-words-1-6'),
	('Soon, the river rose higher and higher','Chẳng mấy chốc, nước sông dâng lên ngày càng cao','00:01:50.800','00:01:54.300','4000-essential-english-words-1-6'),
	('It was very dangerous','Điều này cực kỳ nguy hiểm','00:01:54.300','00:01:56.000','4000-essential-english-words-1-6'),
	('The ghost had helped the children survive','Hồn ma đã giúp lũ trẻ sống sót','00:01:56.000','00:01:59.200','4000-essential-english-words-1-6'),
	('She had saved them from the rising water','Bà ấy đã cứu chúng khỏi dòng nước đang dâng lên','00:01:59.200','00:02:02.000','4000-essential-english-words-1-6'),
	('She also used her power to lead them home','Bà cũng sử dụng sức mạnh của mình để dẫn chúng về nhà','00:02:02.000','00:02:04.800','4000-essential-english-words-1-6'),
	('Sometimes, meeting a ghost has some advantages','Đôi khi, gặp một hồn ma cũng có một vài lợi thế','00:02:04.800','00:02:08.300','4000-essential-english-words-1-6'),
	('A ghost can save your life','Một hồn ma có thể cứu mạng sống của bạn đấy','00:02:08.300','00:02:11.300','4000-essential-english-words-1-6'),

	/* (UUID(),'4000-essential-english-words-1-7','The best prince','Chàng hoàng tử tốt nhất','4000_ESSENTIAL_ENGLISH_WORDS_1_7.mp3',NULL,'00:00:00.000','00:02:17.200','4000-essential-english-words-1',1,1,7) */
	('The best prince','Chàng hoàng tử tốt nhất','00:00:00.960','00:00:03.300','4000-essential-english-words-1-7'),
	('King Minos was very sick','Vua Minos đang bị ốm nặng','00:00:03.300','00:00:05.700','4000-essential-english-words-1-7'),
	('His condition was getting worse','Tình trạng của ông ngày càng xấu hơn','00:00:05.700','00:00:08.200','4000-essential-english-words-1-7'),
	('He had three sons','Ông có ba người con trai','00:00:08.200','00:00:09.900','4000-essential-english-words-1-7'),
	('He loved them all','Ông yêu thương tất cả bọn họ','00:00:09.900','00:00:11.300','4000-essential-english-words-1-7'),
	('He had to announce who would become king','Ông phải tuyên bố ai sẽ trở thành vua','00:00:11.370','00:00:14.600','4000-essential-english-words-1-7'),
	('Two of the princes stood waiting outside the king\'s room','Hai vị hoàng tử đứng chờ bên ngoài phòng của vua','00:00:14.600','00:00:18.670','4000-essential-english-words-1-7'),
	('Theseus was the oldest and strongest','Theseus là người lớn tuổi nhất và là người khỏe nhất','00:00:18.700','00:00:21.770','4000-essential-english-words-1-7'),
	('He thought his father would make him king','Chàng nghĩ rằng cha sẽ chọn mình làm vua','00:00:21.800','00:00:24.700','4000-essential-english-words-1-7'),
	('Pelias, the second son, thought differently','Pelias, người con trai thứ hai, lại nghĩ khác','00:00:24.700','00:00:28.300','4000-essential-english-words-1-7'),
	('He was an expert with weapons','Chàng là một chuyên gia về vũ khí','00:00:28.340','00:00:30.700','4000-essential-english-words-1-7'),
	('He thought the king would choose him','Chàng nghĩ rằng cha mình sẽ chọn mình làm vua','00:00:30.720','00:00:33.200','4000-essential-english-words-1-7'),
	('"When I\'m king," Theseus told Pelias, "I\'ll let you contribute to the defense of our country"','"Khi ta lên làm vua rồi," Theseus nói với Pelias, "ta sẽ để đệ đóng góp đội quân phòng vệ cho đất nước"','00:00:33.200','00:00:40.000','4000-essential-english-words-1-7'),
	('"You can lead the army"','"Đệ có thể lãnh đạo đội quân"','00:00:40.000','00:00:41.800','4000-essential-english-words-1-7'),
	('Pelias became angry','Pelias tức giận','00:00:41.800','00:00:44.200','4000-essential-english-words-1-7'),
	('"Father knows I\'m famous for my sword skills"','"Cha biết rằng ta nổi tiếng về các kỹ năng sử dụng kiếm thuật"','00:00:44.200','00:00:47.850','4000-essential-english-words-1-7'),
	('"He\'ll make me king"','Người sẽ chọn ta làm vua','00:00:48.000','00:00:49.800','4000-essential-english-words-1-7'),
	('"You?" Theseus yelled','"Đệ ư?" Theseus hét lên','00:00:49.800','00:00:51.800','4000-essential-english-words-1-7'),
	('"He won\'t choose you"','"Người sẽ không chọn đệ đâu"','00:00:51.910','00:00:53.800','4000-essential-english-words-1-7'),
	('"The kingdom is mine" Pelias claimed','"Vương quốc này là của ta" Pelias tuyên bố','00:00:53.800','00:00:57.000','4000-essential-english-words-1-7'),
	('"Father will give it to me - or I\'ll use force to take it"','"Cha sẽ trao nó cho ta - hoặc là ta sẽ dùng vũ lực để đoạt lấy"','00:00:57.000','00:01:02.000','4000-essential-english-words-1-7'),
	('Theseus made a sudden move to take out his sword','Theseus đột ngột rút kiếm ra','00:01:02.000','00:01:05.400','4000-essential-english-words-1-7'),
	('Then Pelias did the same','Và rồi Pelias cũng làm như vậy','00:01:05.400','00:01:07.800','4000-essential-english-words-1-7'),
	('"Beating me will be a challenge," Theseus said','"Đánh bại ta sẽ là một thách thức đấy," Theseus nói','00:01:07.800','00:01:11.800','4000-essential-english-words-1-7'),
	('"Fight me now"','"Hãy đấu với ta ngay bây giờ"','00:01:11.800','00:01:13.200','4000-essential-english-words-1-7'),
	('"The winner gets the kingdom" Pelias agreed','"Người chiến thắng sẽ có được vương quốc" Pelias đồng ý','00:01:13.200','00:01:16.800','4000-essential-english-words-1-7'),
	('King Minos could hear his sons fighting','Vua Minos có thể nghe thấy các con trai mình đang đánh nhau','00:01:16.800','00:01:19.800','4000-essential-english-words-1-7'),
	('The youngest son, Jason, stood beside him','Người con trai nhỏ tuổi nhất, Jason, đứng bên cạnh ông','00:01:19.800','00:01:22.900','4000-essential-english-words-1-7'),
	('He sensed his father\'s sadness','Chàng có thể cảm nhận được nỗi buồn của cha mình','00:01:22.950','00:01:25.900','4000-essential-english-words-1-7'),
	('The king laid his hand flat on Jason\'s arm','Nhà vua đặt tay mình lên cánh tay của Jason','00:01:25.900','00:01:29.300','4000-essential-english-words-1-7'),
	('"Your brothers fight too much," the king told him','"Các anh của con đấu đá nhau rất nhiều," nhà vua nói','00:01:29.300','00:01:32.800','4000-essential-english-words-1-7'),
	('"I must protect my kingdom from all harm"','"Ta phải bảo vệ vương quốc của mình khỏi tất cả mối nguy hại"','00:01:32.800','00:01:36.200','4000-essential-english-words-1-7'),
	('"They\'ll divide it between them"','"Chúng sẽ chia cắt vương quốc này ra mất"','00:01:36.300','00:01:38.250','4000-essential-english-words-1-7'),
	('"The people won\'t know what to do"','"Người dân sẽ chẳng biết phải làm gì"','00:01:38.300','00:01:40.700','4000-essential-english-words-1-7'),
	('"There\'ll be war"','"Chiến tranh sẽ xảy ra"','00:01:40.700','00:01:42.100','4000-essential-english-words-1-7'),
	('"I can\'t allow either of them to be king"','"Cha không thể cho phép bất cứ ai trong chúng làm vua"','00:01:42.200','00:01:45.700','4000-essential-english-words-1-7'),
	('"Therefore, I\'m making you king"','"Bởi vậy, cha sẽ để con làm vua"','00:01:45.700','00:01:48.800','4000-essential-english-words-1-7'),
	('"Your kindness has always made you special"','"Lòng nhân hậu của con đã luôn khiến con trở nên đặc biệt"','00:01:48.800','00:01:51.800','4000-essential-english-words-1-7'),
	('"It\'s the difference between you and your brothers"','"Đó là sự khác biệt giữa con và các anh trai của con"','00:01:51.800','00:01:55.400','4000-essential-english-words-1-7'),
	('"You can bring peace"','"Con có thể mang đến hòa bình"','00:01:55.450','00:01:56.990','4000-essential-english-words-1-7'),
	('"They can\'t"','"Chúng nó thì không thể"','00:01:57.100','00:01:58.600','4000-essential-english-words-1-7'),
	('Then the king died','Sau đó nhà vua qua đời','00:01:58.600','00:02:00.500','4000-essential-english-words-1-7'),
	('Theseus and Pelias heard that their youngest brother was king','Theseus và Pelias nghe nói rằng cậu em trai nhỏ nhất được làm vua','00:02:00.500','00:02:04.300','4000-essential-english-words-1-7'),
	('They were surprised','Họ đều bất ngờ','00:02:04.300','00:02:05.780','4000-essential-english-words-1-7'),
	('They realized that their fighting was wrong','Họ nhận ra cuộc chiến của họ là sai lầm','00:02:05.860','00:02:08.600','4000-essential-english-words-1-7'),
	('It had kept them from saying goodbye to their father','Điều đó khiến họ không thể nói lời tạm biệt tới cha mình','00:02:08.600','00:02:11.800','4000-essential-english-words-1-7'),
	('They agreed to have Jason as their king','Họ đồng ý Jason làm vua','00:02:11.800','00:02:14.800','4000-essential-english-words-1-7'),
	('He was the best choice','Chàng là sự lựa chọn tốt nhất','00:02:14.800','00:02:17.200','4000-essential-english-words-1-7'),

	/* (UUID(),'4000-essential-english-words-1-8','How the sun and the moon were made?','Mặt trời và mặt trăng được sinh ra bằng cách nào?','4000_ESSENTIAL_ENGLISH_WORDS_1_8.mp3',NULL,'00:00:00.000','00:02:10.000','4000-essential-english-words-1',1,0,8) */
	('How the sun and the moon were made?','Mặt trời và mặt trăng được sinh ra bằng cách nào?','00:00:00.960','00:00:04.000','4000-essential-english-words-1-8'),
	('Do you ever wonder where the moon and the sun came from?','Bạn có từng tự hỏi Mặt Trăng và Mặt Trời đến từ đâu không?','00:00:04.000','00:00:08.800','4000-essential-english-words-1-8'),
	('The Inuit people of Alaska have a theory','Người dân Inuit ở Alaska có một giả thuyết như thế này','00:00:08.800','00:00:11.650','4000-essential-english-words-1-8'),
	('They tell a story about a beautiful girl','Họ kể một câu chuyện về một cô gái xinh đẹp','00:00:11.650','00:00:15.300','4000-essential-english-words-1-8'),
	('She was very nice','Cô ấy rất tốt bụng','00:00:15.100','00:00:17.400','4000-essential-english-words-1-8'),
	('In contrast, her brother was a mean little boy','Nhưng ngược lại, anh trai cô lại là một cậu bé xấu tính','00:00:17.400','00:00:21.800','4000-essential-english-words-1-8'),
	('One day he proposed something','Một ngày nọ anh ta đề nghị một điều rằng','00:00:21.800','00:00:24.300','4000-essential-english-words-1-8'),
	('"We should go to a party," he said','"Chúng ta hãy đi dự tiệc đi," anh ta nói','00:00:24.300','00:00:27.900','4000-essential-english-words-1-8'),
	('The girl accepted','Cô gái đồng ý','00:00:27.900','00:00:29.400','4000-essential-english-words-1-8'),
	('First, it was necessary for her to prepare','Trước tiên, cô cần chuẩn bị','00:00:29.400','00:00:32.600','4000-essential-english-words-1-8'),
	('She arranged her hair and put on nice clothes','Cô sửa soạn mái tóc và khoác lên mình những bộ quần áo thật đẹp','00:00:32.600','00:00:35.800','4000-essential-english-words-1-8'),
	('This required a lot of time','Việc này yêu cầu khá nhiều thời gian','00:00:35.800','00:00:38.500','4000-essential-english-words-1-8'),
	('But the girl worked hard, and soon she had success','Nhưng cô bé đã làm việc chăm chỉ và chẳng mấy chốc đã thành công','00:00:38.500','00:00:42.600','4000-essential-english-words-1-8'),
	('She looked perfect','Trông cô ấy thật hoàn hảo','00:00:42.600','00:00:44.800','4000-essential-english-words-1-8'),
	('They attended the party together','Họ tham gia bữa tiệc cùng nhau','00:00:44.800','00:00:47.300','4000-essential-english-words-1-8'),
	('The girl was having fun','Cô gái rất vui','00:00:47.300','00:00:49.300','4000-essential-english-words-1-8'),
	('Later, she walked into the bathroom','Lát sau, cô đi vào trong phòng tắm','00:00:49.300','00:00:52.200','4000-essential-english-words-1-8'),
	('Suddenly, the lights were turned off','Bất chợt, tất cả đèn trong phòng đều vụt tắt','00:00:52.200','00:00:54.750','4000-essential-english-words-1-8'),
	('Someone grabbed her hair and tore her clothes','Có ai đó đã nắm tóc và xé quần áo của cô','00:00:54.800','00:00:58.600','4000-essential-english-words-1-8'),
	('She ran out of the bathroom','Cô vội chạy ra khỏi phòng tắm','00:00:58.600','00:01:00.700','4000-essential-english-words-1-8'),
	('She wanted to know who did this to her','Cô muốn biết ai đã làm điều này với mình','00:01:00.700','00:01:03.500','4000-essential-english-words-1-8'),
	('Then she had an idea','Rồi cô nảy ra một ý tưởng','00:01:03.500','00:01:05.350','4000-essential-english-words-1-8'),
	('She fixed her hair again','Cô sửa sang lại mái tóc một lần nữa','00:01:05.350','00:01:07.800','4000-essential-english-words-1-8'),
	('This time it was even more beautiful','Lần này thậm chí còn xinh đẹp hơn bội phần','00:01:07.800','00:01:10.300','4000-essential-english-words-1-8'),
	('She even balanced beautiful jewels in it','Thậm chí cô còn chỉnh các món trang sức tuyệt đẹp cân xứng với mái tóc','00:01:10.300','00:01:13.350','4000-essential-english-words-1-8'),
	('She wanted to encourage the person to grab it again','Cô muốn cổ vũ người đó nắm tóc thêm lần nữa','00:01:13.350','00:01:16.800','4000-essential-english-words-1-8'),
	('She put black dirt in her hair','Cô bôi đất bẩn lên tóc mình','00:01:16.800','00:01:19.800','4000-essential-english-words-1-8'),
	('The purpose of this was to catch the person','Mục đích của việc này là để bắt lấy kẻ kia','00:01:19.800','00:01:22.800','4000-essential-english-words-1-8'),
	('She went to the bathroom again, and it was the same pattern','Cô lại đi vào phòng tắm lần nữa, và vẫn y như kiểu trước','00:01:22.800','00:01:26.700','4000-essential-english-words-1-8'),
	('The lights went off, and someone grabbed her hair','Những bóng đèn lại vụt tắt, có ai đó túm lấy tóc cô','00:01:26.700','00:01:29.800','4000-essential-english-words-1-8'),
	('When he released it, his hand was black','Khi hắn thả nó ra, tay của hắn đen thui','00:01:29.800','00:01:33.200','4000-essential-english-words-1-8'),
	('The girl returned to the party','Cô gái quay trở lại bữa tiệc','00:01:33.200','00:01:35.200','4000-essential-english-words-1-8'),
	('She knew there was only a single person with a black hand','Cô biết là chỉ có duy nhất một người với bàn tay màu đen','00:01:35.200','00:01:39.200','4000-essential-english-words-1-8'),
	('When she saw that person, he was very familiar','Khi cô nhìn thấy hắn, hắn rất quen thuộc','00:01:39.200','00:01:42.750','4000-essential-english-words-1-8'),
	('It was her brother','Đó là anh trai của cô','00:01:42.750','00:01:44.700','4000-essential-english-words-1-8'),
	('He ran into the woods','Hắn liền bỏ chạy vào rừng','00:01:44.700','00:01:46.600','4000-essential-english-words-1-8'),
	('The girl ran after him','Cô gái đuổi theo sau hắn','00:01:46.600','00:01:48.400','4000-essential-english-words-1-8'),
	('They both carried fire so they could see in the dark','Cả hai người đều mang theo đuốc vì thế họ có thể nhìn thấy trong bóng tối','00:01:48.400','00:01:51.500','4000-essential-english-words-1-8'),
	('The smoke went into the air','Khói liền hòa vào không khí','00:01:51.500','00:01:53.800','4000-essential-english-words-1-8'),
	('As they ran, they grew','Trong khi họ mải miết chạy, họ đã lớn lên','00:01:53.800','00:01:55.740','4000-essential-english-words-1-8'),
	('They became huge','Họ biến thành khổng lồ','00:01:55.740','00:01:57.740','4000-essential-english-words-1-8'),
	('Then they went into space','Rồi họ tiến vào không gian','00:01:57.740','00:01:59.710','4000-essential-english-words-1-8'),
	('When the girl\'s fire went out, she hung in the sky','Khi ngọn đuốc của cô gái tắt, cô đã treo lơ lửng ở trên bầu trời','00:01:59.710','00:02:03.300','4000-essential-english-words-1-8'),
	('She became the moon, and her brother became the sun','Cô biến thành Mặt Trăng, còn anh trai cô trở thành Mặt Trời','00:02:03.300','00:02:07.000','4000-essential-english-words-1-8'),
	('They chase each other forever','Họ cứ đuổi nhau mãi như vậy','00:02:07.000','00:02:10.000','4000-essential-english-words-1-8'),

	/* (UUID(),'4000-essential-english-words-1-9','The starfish','Chú sao biển','4000_ESSENTIAL_ENGLISH_WORDS_1_9.mp3',NULL,'00:00:00.000','00:01:52.000','4000-essential-english-words-1',1,0,9) */
	('The starfish','Chú sao biển','00:00:00.960','00:00:02.900','4000-essential-english-words-1-9'),
	('Last summer I took a trip to an island','Mùa hè năm ngoái tôi đã đi du lịch đến một hòn đảo','00:00:02.900','00:00:06.300','4000-essential-english-words-1-9'),
	('I had a lot of fun','Tôi đã rất vui','00:00:06.300','00:00:08.300','4000-essential-english-words-1-9'),
	('I sat and watched the waves and listened to the ocean','Tôi ngồi và ngắm nhìn sóng biển và lắng nghe đại dương','00:00:08.350','00:00:12.300','4000-essential-english-words-1-9'),
	('I learned to identify birds','Tôi học cách nhận biết các loài chim','00:00:12.300','00:00:14.800','4000-essential-english-words-1-9'),
	('I discovered pretty things and enjoyed the taste of new foods','Tôi đã khám phá ra những điều rất thú vị và thích hương vị của những món ăn mới lạ','00:00:14.800','00:00:19.400','4000-essential-english-words-1-9'),
	('It was a very nice time','Đó là khoảng thời gian rất tuyệt vời','00:00:19.400','00:00:21.800','4000-essential-english-words-1-9'),
	('One evening I took a pleasant walk by the ocean','Một buổi tối nọ, tôi thích thú đi dạo bên bờ biển','00:00:21.800','00:00:25.400','4000-essential-english-words-1-9'),
	('When the waves came in, many starfish fell on the beach','Khi những cơn sóng xô tới, rất nhiều con sao biển bị dạt vào bờ','00:00:25.450','00:00:29.800','4000-essential-english-words-1-9'),
	('Some starfish went back into the water, and they were safe','Một vài con sao biển đã quay trở lại làn nước, và chúng được an toàn','00:00:29.800','00:00:34.400','4000-essential-english-words-1-9'),
	('But other starfish were still on the sand','Nhưng những con sao biển khác vẫn còn nằm trên cát','00:00:34.400','00:00:37.800','4000-essential-english-words-1-9'),
	('They would die if they did not get into the water','Chúng sẽ chết nếu không được đưa xuống nước','00:00:37.800','00:00:41.000','4000-essential-english-words-1-9'),
	('There were many starfish on the beach that night','Có rất nhiều sao biển ở trên bờ biển vào tối hôm đó','00:00:41.000','00:00:44.300','4000-essential-english-words-1-9'),
	('It made me sad, but I knew I could not fix the problem','Điều này làm tôi cảm thấy buồn, nhưng tôi biết tôi không thể giải quyết vấn đề này được','00:00:44.300','00:00:48.450','4000-essential-english-words-1-9'),
	('I stepped very carefully so I did not damage them','Tôi bước rất cẩn thận để không làm tổn thương chúng','00:00:48.550','00:00:52.400','4000-essential-english-words-1-9'),
	('Then I saw a little girl','Rồi tôi thấy một cô bé','00:00:52.400','00:00:54.930','4000-essential-english-words-1-9'),
	('She was also sad about the starfish','Cô bé cũng buồn vì những con sao biển','00:00:54.950','00:00:57.900','4000-essential-english-words-1-9'),
	('She wanted to prevent all of them from dying','Cô muốn ngăn tất cả chúng khỏi việc chết dần','00:00:57.900','00:01:01.400','4000-essential-english-words-1-9'),
	('She asked me if I could perhaps help her','Cô bé hỏi tôi rằng liệu tôi có thể giúp cô không','00:01:01.400','00:01:04.700','4000-essential-english-words-1-9'),
	('"To be frank, I don\'t think we can do anything," I said','"Thật lòng thì chú không nghĩ chúng ta có thể làm được điều gì đâu," tôi nói','00:01:04.700','00:01:08.800','4000-essential-english-words-1-9'),
	('The little girl started to cry','Cô bé bắt đầu khóc','00:01:08.800','00:01:11.100','4000-essential-english-words-1-9'),
	('She sat back against a rock and thought for a while','Cô ngồi dựa lưng vào một tảng đá và nghĩ một lúc','00:01:11.100','00:01:15.000','4000-essential-english-words-1-9'),
	('Finally, the emotion was gone','Cuối cùng, khi cảm xúc đó qua đi','00:01:15.000','00:01:17.700','4000-essential-english-words-1-9'),
	('She stopped crying and stood up','Cô bé ngừng khóc và đứng dậy','00:01:17.700','00:01:20.700','4000-essential-english-words-1-9'),
	('Then she picked up a starfish and threw it into the water','Rồi cô bé nhặt một con sao biển lên và ném nó xuống nước','00:01:20.720','00:01:24.600','4000-essential-english-words-1-9'),
	('"What are you doing?" I asked her','"Cháu đang làm gì vậy?" tôi hỏi cô bé','00:01:24.600','00:01:27.100','4000-essential-english-words-1-9'),
	('But she did not answer me','Nhưng cô nhóc không trả lời tôi','00:01:27.100','00:01:28.550','4000-essential-english-words-1-9'),
	('She just threw as many starfish as she could','Cô bé chỉ ném nhiều sao biển xuống nước hết sức có thể','00:01:28.650','00:01:31.800','4000-essential-english-words-1-9'),
	('"You cannot save all of them" I said','"Cháu không thể cứu tất cả chúng" tôi nói','00:01:31.900','00:01:35.100','4000-essential-english-words-1-9'),
	('She stopped to look at me','Cô bé dừng lại nhìn tôi','00:01:35.100','00:01:37.000','4000-essential-english-words-1-9'),
	('"No, I cannot save them all," she replied','"Không, cháu không thể cứu tất cả," cô bé đáp lại','00:01:37.000','00:01:40.450','4000-essential-english-words-1-9'),
	('Then she picked up a very big starfish and said, "But I can save this one"','Rồi cô nhặt một con sao biển rất lớn lên và nói: "Nhưng cháu có thể cứu sống con này"','00:01:40.520','00:01:45.800','4000-essential-english-words-1-9'),
	('And then she smiled and threw the starfish as far as she could into the ocean','Và rồi cô bé mỉm cười và ném con sao biển ấy xa nhất có thể vào đại dương bao la','00:01:45.800','00:01:52.000','4000-essential-english-words-1-9'),

	/* (UUID(),'4000-essential-english-words-1-10','The first peacock','Con công đầu tiên','4000_ESSENTIAL_ENGLISH_WORDS_1_10.mp3',NULL,'00:00:00.000','00:02:01.000','4000-essential-english-words-1',1,0,10) */
	('The First Peacock','Con công đầu tiên','00:00:00.960','00:00:03.000','4000-essential-english-words-1-10'),
	('Argos lived in Ancient Greece','Argos sống ở Hy Lạp cổ đại','00:00:03.000','00:00:05.900','4000-essential-english-words-1-10'),
	('He was a husband and a proud father','Anh ấy là một người chồng và một người cha đáng tự hào','00:00:05.900','00:00:08.900','4000-essential-english-words-1-10'),
	('He worked hard and did well at his job','Anh ấy làm việc chăm chỉ và làm tốt công việc của mình','00:00:08.900','00:00:11.900','4000-essential-english-words-1-10'),
	('But one thing about him wasn\'t normal','Nhưng có một điều không bình thường về anh ấy','00:00:11.900','00:00:14.700','4000-essential-english-words-1-10'),
	('He was born with 100 eyes','Anh ấy sinh ra với 100 con mắt','00:00:14.700','00:00:17.600','4000-essential-english-words-1-10'),
	('Having many eyes was usually a benefit to him','Việc có nhiều mắt thường mang lại lợi ích cho anh ấy','00:00:17.600','00:00:21.300','4000-essential-english-words-1-10'),
	('He had a chance to see many things','Anh có cơ hội nhìn thấy nhiều thứ','00:00:21.300','00:00:24.000','4000-essential-english-words-1-10'),
	('Also, since he had so many eyes, he was very good at guarding things','Hơn nữa, vì có nhiều mắt nên anh ấy rất giỏi canh gác mọi thứ','00:00:24.000','00:00:29.300','4000-essential-english-words-1-10'),
	('While sleeping, he only rested a few eyes at a time','Trong khi ngủ, anh chỉ nghỉ ngơi lần lượt vài con mắt','00:00:29.300','00:00:33.400','4000-essential-english-words-1-10'),
	('The others stayed awake','Những con mắt khác vẫn thức','00:00:33.400','00:00:35.200','4000-essential-english-words-1-10'),
	('He worked for Hera, a great goddess','Anh làm việc cho Hera, một nữ thần vĩ đại','00:00:35.200','00:00:38.000','4000-essential-english-words-1-10'),
	('His primary function was to guard a special cow','Nhiệm vụ chính của anh là bảo vệ một con bò đặc biệt','00:00:38.000','00:00:41.600','4000-essential-english-words-1-10'),
	('The cow was very important to Hera','Con bò rất quan trọng đối với Hera','00:00:41.600','00:00:43.880','4000-essential-english-words-1-10'),
	('It was her favorite pet','Đó là thú cưng yêu thích của cô','00:00:43.900','00:00:45.800','4000-essential-english-words-1-10'),
	('The most essential part of his job was to keep the cow alone','Phần quan trọng nhất trong công việc của anh là giữ con bò một mình','00:00:45.800','00:00:49.800','4000-essential-english-words-1-10'),
	('It had to be kept separate from all the other cows and far away from people','Nó phải được giữ tách biệt khỏi tất cả những con bò khác và cách xa mọi người','00:00:49.800','00:00:55.0000','4000-essential-english-words-1-10'),
	('This was an easy job for Argos','Đây là một công việc dễ dàng đối với Argos','00:00:55.000','00:00:57.800','4000-essential-english-words-1-10'),
	('The cow just ate grass all day','Con bò chỉ ăn cỏ cả ngày','00:00:57.800','00:01:00.800','4000-essential-english-words-1-10'),
	('But the god Zeus wanted the cow','Nhưng thần Zeus lại muốn con bò','00:01:00.800','00:01:03.200','4000-essential-english-words-1-10'),
	('He wanted to take it away from Hera','Ông ta muốn lấy nó khỏi Hera','00:01:03.200','00:01:05.900','4000-essential-english-words-1-10'),
	('He had a plan','Ông có một kế hoạch','00:01:05.900','00:01:07.900','4000-essential-english-words-1-10'),
	('He found a great music player','Ông tìm thấy một người chơi nhạc tuyệt vời','00:01:07.900','00:01:10.900','4000-essential-english-words-1-10'),
	('He asked the man to play a beautiful song for Argos','Ông yêu cầu người đàn ông chơi một bài hát thật hay cho Argos nghe','00:01:10.900','00:01:14.900','4000-essential-english-words-1-10'),
	('Zeus was certain Argos would go to sleep','Zeus chắc chắn Argos sẽ chìm vào giấc ngủ','00:01:14.900','00:01:18.300','4000-essential-english-words-1-10'),
	('The song had an immediate effect','Bài hát có tác dụng ngay lập tức','00:01:18.300','00:01:21.000','4000-essential-english-words-1-10'),
	('Argos couldn\'t focus on his job','Argos không thể tập trung vào công việc','00:01:21.000','00:01:23.800','4000-essential-english-words-1-10'),
	('He fell asleep','Anh đã ngủ quên','00:01:23.800','00:01:25.700','4000-essential-english-words-1-10'),
	('Zeus saw this, and he took the cow','Zeus thấy vậy và lấy đi con bò','00:01:25.700','00:01:28.600','4000-essential-english-words-1-10'),
	('Hera was very angry with Argos','Hera rất tức giận với Argos','00:01:28.600','00:01:31.600','4000-essential-english-words-1-10'),
	('She turned him into a peacock','Cô biến anh thành một con công','00:01:31.600','00:01:34.000','4000-essential-english-words-1-10'),
	('She put his many eyes on his tail','Cô đặt nhiều mắt trên chiếc đuôi anh','00:01:34.000','00:01:37.000','4000-essential-english-words-1-10'),
	('Argos was very sad','Argos rất buồn','00:01:37.000','00:01:39.700','4000-essential-english-words-1-10'),
	('Zeus saw how much trouble he had caused Argos','Zeus thấy mình đã gây ra bao nhiêu rắc rối cho Argos','00:01:39.700','00:01:43.500','4000-essential-english-words-1-10'),
	('He made another plan','Ông đã thực hiện một kế hoạch khác','00:01:43.500','00:01:45.400','4000-essential-english-words-1-10'),
	('He turned Argos into a group of stars','Ông biến Argos thành một tốp các ngôi sao','00:01:45.400','00:01:48.400','4000-essential-english-words-1-10'),
	('He wanted Argos to remain in the sky forever','Ông muốn Argos vẫn luôn ở trên bầu trời mãi mãi','00:01:48.400','00:01:51.900','4000-essential-english-words-1-10'),
	('Even today, Argos\' image remains there, above the site where all his problems began','Thậm chí cho tới ngày nay, hình ảnh của Argos vẫn còn ở đó, ngay trên nơi mà tất cả những rắc rối của anh bắt đầu','00:01:51.900','00:01:58.500','4000-essential-english-words-1-10'),
	('We can still see him in the night sky','Chúng ta vẫn có thể nhìn thấy anh ấy trên bầu trời đêm','00:01:58.500','00:02:01.000','4000-essential-english-words-1-10');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-1-11','Princess Rose and the creature','Công chúa Hoa Hồng và các sinh Vật','4000_ESSENTIAL_ENGLISH_WORDS_1_11.mp3',NULL,'00:00:00.000','00:02:04.000','4000-essential-english-words-1',0,0,11) */
	('Princess Rose and the Creature','Công chúa Hoa Hồng và Sinh Vật','00:00:00.960','00:00:03.800','4000-essential-english-words-1-11'),
	('There was once a beautiful princess named Rose','Thuở xa xưa có một nàng công chúa xinh đẹp tên là Rose','00:00:03.800','00:00:07.400','4000-essential-english-words-1-11'),
	('Her mother, the queen, however, was not as beautiful as the princess','Mẹ của nàng, hoàng hậu, trái lại, không xinh đẹp bằng công chúa','00:00:07.400','00:00:12.500','4000-essential-english-words-1-11'),
	('The queen felt bad that she was not the most beautiful woman in the kingdom anymore','Nữ hoàng cảm thấy tồi tệ vì bà không còn là người phụ nữ đẹp nhất trong vương quốc nữa','00:00:12.500','00:00:18.000','4000-essential-english-words-1-11'),
	('She was tired of competing with her daughter','Bà kiệt sức vì phải tranh đấu với con gái','00:00:18.000','00:00:21.400','4000-essential-english-words-1-11'),
	('She made a decision','Bà đã đưa ra một quyết định','00:00:21.400','00:00:23.200','4000-essential-english-words-1-11'),
	('She prepared a drink for the princess','Bà chuẩn bị đồ uống cho công chúa','00:00:23.200','00:00:26.200','4000-essential-english-words-1-11'),
	('After the princess drank it, she fell asleep','Sau khi công chúa uống hết, nàng đã ngủ thiếp đi','00:00:26.200','00:00:29.600','4000-essential-english-words-1-11'),
	('Then the queen took the princess to the forest','Sau đó hoàng hậu đưa công chúa vào rừng','00:00:29.600','00:00:32.530','4000-essential-english-words-1-11'),
	('She left the princess there','Bà ta bỏ lại công chúa ở đó','00:00:32.680','00:00:34.400','4000-essential-english-words-1-11'),
	('It was a very serious thing to do','Đó là một điều rất nghiêm trọng','00:00:34.800','00:00:37.100','4000-essential-english-words-1-11'),
	('"Either she will be killed by animals or she will get lost in the forest," the queen thought','"Hoặc là nàng sẽ bị giết bởi các loài vật, hoặc là nàng sẽ lạc lối ở trong rừng," hoàng hậu thầm nghĩ','00:00:37.100','00:00:43.330','4000-essential-english-words-1-11'),
	('The princess had a dream','Công chúa mơ một giấc mơ','00:00:43.400','00:00:45.100','4000-essential-english-words-1-11'),
	('She dreamed about a man with brown hair and brown eyes','Nàng mơ thấy một người đàn ông tóc nâu và mắt nâu','00:00:45.100','00:00:49.000','4000-essential-english-words-1-11'),
	('It was the man she would wed','Đó là người đàn ông nàng sẽ kết hôn','00:00:49.050','00:00:50.930','4000-essential-english-words-1-11'),
	('The princess woke up','Công chúa chợt tỉnh giấc','00:00:50.950','00:00:52.800','4000-essential-english-words-1-11'),
	('She saw a strange creature on the ground','Nàng thấy một sinh vật kỳ lạ trên mặt đất','00:00:52.800','00:00:55.800','4000-essential-english-words-1-11'),
	('It looked like a man, but he was hairy and green','Thoạt nhìn giống như một người đàn ông, nhưng hắn ta lại đầy lông lá và có màu xanh lục','00:00:55.800','00:00:59.800','4000-essential-english-words-1-11'),
	('He had horns on his head and a pig\'s nose','Hắn có cặp sừng ở trên đầu và một chiếc mũi lợn','00:00:59.800','00:01:03.300','4000-essential-english-words-1-11'),
	('The creature said, "Did I scare you?"','Sinh vật đó lên tiếng: "Ta làm ngươi sợ à?"','00:01:03.300','00:01:06.800','4000-essential-english-words-1-11'),
	('"I hope not"','Ta mong rằng không phải vậy','00:01:06.850','00:01:08.200','4000-essential-english-words-1-11'),
	('"Let me introduce myself"','Cho phép ta tự giới thiệu về mình','00:01:08.200','00:01:10.230','4000-essential-english-words-1-11'),
	('"I am Henry"','Ta tên là Henry','00:01:10.300','00:01:11.500','4000-essential-english-words-1-11'),
	('"I am not scared"','Ta không sợ gì cả','00:01:11.500','00:01:13.400','4000-essential-english-words-1-11'),
	('"To tell you the truth, I think you are cute," said Rose','"Thật lòng mà nói, ta nghĩ nàng rất dễ thương," Rose nói','00:01:13.400','00:01:17.450','4000-essential-english-words-1-11'),
	('Rose and Henry spent the day together','Rose và Henry đã dành cả ngày bên nhau','00:01:17.650','00:01:20.400','4000-essential-english-words-1-11'),
	('They collected berries, caught fish, and had lunch','Họ thu nhặt quả mọng, bắt cá và ăn trưa','00:01:20.400','00:01:24.300','4000-essential-english-words-1-11'),
	('They had a very good day filled with nice conversations','Họ đã có một ngày vô cùng tốt đẹp tràn ngập những cuộc trò chuyện thú vị','00:01:24.300','00:01:28.900','4000-essential-english-words-1-11'),
	('"Rose, I have to go home," said Henry','"Rose, ta phải về nhà rồi," Henry nói','00:01:29.000','00:01:32.900','4000-essential-english-words-1-11'),
	('"My ship will sail home soon"','Con tàu của ta sẽ sớm ra khơi trở về nhà','00:01:32.900','00:01:35.250','4000-essential-english-words-1-11'),
	('"I can\'t leave you here in the forest alone"','Ta không thể bỏ em lại đây một mình trong rừng được','00:01:35.300','00:01:38.300','4000-essential-english-words-1-11'),
	('"Will you come with me?"','"Em sẽ đi cùng ta chứ?"','00:01:38.300','00:01:40.200','4000-essential-english-words-1-11'),
	('Rose was very happy','Rose vô cùng hạnh phúc','00:01:40.200','00:01:42.200','4000-essential-english-words-1-11'),
	('She gave Henry a kiss right on his pig nose','Nàng trao cho Henry một nụ hôn ngay lên chiếc mũi heo của anh','00:01:42.200','00:01:45.600','4000-essential-english-words-1-11'),
	('As soon as she kissed Henry, he began to change','Ngay lúc nàng hôn Henry, anh ta đã bắt đầu biến đổi','00:01:45.600','00:01:49.600','4000-essential-english-words-1-11'),
	('His pig nose turned into a man\'s nose','Chiếc mũi heo của anh ta biến thành chiếc mũi người','00:01:49.600','00:01:52.600','4000-essential-english-words-1-11'),
	('His horns and green hair went away','Cặp sừng và mái tóc xanh của anh ta biến mất','00:01:52.600','00:01:55.600','4000-essential-english-words-1-11'),
	('Standing in front of her was the man Rose had dreamt about','Đứng trước mặt nàng là người đàn ông mà Rose đã mơ thấy','00:01:55.600','00:02:00.000','4000-essential-english-words-1-11'),
	('Rose and Henry were married, and they lived happily','Rose và Henry kết hôn, và họ sống hạnh phúc','00:02:00.000','00:02:04.000','4000-essential-english-words-1-11'),

	/* (UUID(),'4000-essential-english-words-1-12','The crazy artist','Người nghệ sĩ điên','4000_ESSENTIAL_ENGLISH_WORDS_1_12.mp3',NULL,'00:00:00.000','00:02:11.500','4000-essential-english-words-1',0,0,12) */
	('The Crazy Artist','Người nghệ sĩ điên','00:00:00.960','00:00:03.800','4000-essential-english-words-1-12'),
	('Frenhofer was the best artist in the world','Frenhofer là nghệ sĩ giỏi nhất thế giới','00:00:03.800','00:00:06.800','4000-essential-english-words-1-12'),
	('Everyone loved him','Mọi người đều yêu mến anh ấy','00:00:06.800','00:00:08.800','4000-essential-english-words-1-12'),
	('The quality of his paintings was very high','Chất lượng các bức tranh của anh ấy rất cao','00:00:08.800','00:00:12.000','4000-essential-english-words-1-12'),
	('He always used the best materials','Anh luôn sử dụng những nguyên liệu tốt nhất','00:00:12.000','00:00:15.000','4000-essential-english-words-1-12'),
	('He made a big profit from his paintings','Anh kiếm được một khoản lợi nhuận lớn từ những bức tranh của mình','00:00:15.000','00:00:18.000','4000-essential-english-words-1-12'),
	('He had delicious meals with his rich neighbors','Anh có những bữa ăn ngon cùng những người hàng xóm giàu có','00:00:18.000','00:00:21.300','4000-essential-english-words-1-12'),
	('He taught art classes','Anh dạy các lớp vẽ','00:00:21.300','00:00:23.200','4000-essential-english-words-1-12'),
	('Life was good','Cuộc sống rất tốt đẹp','00:00:23.200','00:00:25.000','4000-essential-english-words-1-12'),
	('Then his attitude changed','Rồi thái độ của anh ấy thay đổi','00:00:25.000','00:00:27.400','4000-essential-english-words-1-12'),
	('He stopped selling paintings and teaching','Anh không còn bán tranh và dạy học nữa','00:00:27.400','00:00:30.000','4000-essential-english-words-1-12'),
	('He tried a new method of painting','Anh đã thử một phương pháp vẽ tranh mới','00:00:30.000','00:00:32.800','4000-essential-english-words-1-12'),
	('He stayed alone in his apartment all day','Anh ở một mình trong căn hộ cả ngày','00:00:32.800','00:00:35.800','4000-essential-english-words-1-12'),
	('He worked all day and all night, rarely eating','Anh làm việc cả ngày lẫn đêm, hiếm khi ăn','00:00:35.800','00:00:39.300','4000-essential-english-words-1-12'),
	('Soon Frenhofer became very thin','Không lâu sau Frenhofer dần trở nên vô cùng gầy gò','00:00:39.300','00:00:42.200','4000-essential-english-words-1-12'),
	('But he kept working on the same painting for many years','Nhưng anh vẫn tiếp tục làm việc trên cùng bức tranh trong nhiều năm','00:00:42.200','00:00:46.000','4000-essential-english-words-1-12'),
	('He worked as hard as he could','Anh làm việc chăm chỉ nhất có thể','00:00:46.000','00:00:48.400','4000-essential-english-words-1-12'),
	('Finally, he finished the painting','Cuối cùng, anh đã hoàn thành bức tranh','00:00:48.400','00:00:51.300','4000-essential-english-words-1-12'),
	('He was very happy and invited other artists to see it','Anh vô cùng vui mừng và mời những họa sĩ khác đến xem','00:00:51.300','00:00:54.800','4000-essential-english-words-1-12'),
	('"I want your professional opinion," he said','"Tôi muốn ý kiến chuyên môn của mọi người" anh ấy nói','00:00:54.800','00:00:57.800','4000-essential-english-words-1-12'),
	('He wanted them to judge it and compare it to other paintings','Anh muốn họ đánh giá và so sánh nó với những bức tranh khác','00:00:57.800','00:01:01.800','4000-essential-english-words-1-12'),
	('Everyone was very excited as they went up the stairs to his apartment','Mọi người đều rất háo hức khi họ đi lên cầu thang tới căn hộ của anh ấy','00:01:01.800','00:01:06.400','4000-essential-english-words-1-12'),
	('Frenhofer was excited to show his painting, and the artists were excited to see it','Frenhofer rất háo hức khoe bức tranh của mình, và các nghệ sĩ cũng rất mong mỏi được xem nó','00:01:06.400','00:01:11.400','4000-essential-english-words-1-12'),
	('"They\'ll love it," he thought','"Họ sẽ thích nó," anh ta nghĩ','00:01:11.400','00:01:14.400','4000-essential-english-words-1-12'),
	('But they did not','Nhưng họ thì không','00:01:14.400','00:01:16.800','4000-essential-english-words-1-12'),
	('They were surprised by his painting','Họ ngạc nhiên bởi bức vẽ của anh','00:01:16.800','00:01:19.400','4000-essential-english-words-1-12'),
	('There was no white anywhere','Không hề có màu trắng ở đâu cả','00:01:19.500','00:01:21.900','4000-essential-english-words-1-12'),
	('Frenhofer filled the whole painting with lines and colors','Frenhofer lấp đầy toàn bộ bức tranh bằng những đường nét và màu sắc','00:01:21.900','00:01:25.800','4000-essential-english-words-1-12'),
	('There was no space for a normal picture','Không hề có khoảng trống cho một bức tranh bình thường','00:01:25.800','00:01:28.800','4000-essential-english-words-1-12'),
	('It was full of strange shapes','Nó đầy những hình thù kỳ lạ','00:01:28.800','00:01:30.800','4000-essential-english-words-1-12'),
	('It looked bad to the other artists','Với các nghệ sĩ khác, nó trông tệ hại','00:01:30.800','00:01:33.800','4000-essential-english-words-1-12'),
	('He used symbols, and they didn\'t understand them','Anh sử dụng các ký hiệu và họ không hiểu chúng','00:01:33.800','00:01:37.300','4000-essential-english-words-1-12'),
	('They thought it was terrible','Họ nghĩ nó thật tệ hại','00:01:37.300','00:01:39.400','4000-essential-english-words-1-12'),
	('"Why did you paint this strange picture?" someone asked','"Tại sao cậu lại vẽ bức tranh kỳ lạ này?" ai đó hỏi','00:01:39.400','00:01:43.000','4000-essential-english-words-1-12'),
	('They didn\'t understand its beauty','Họ không thể hiểu được vẻ đẹp của nó','00:01:43.050','00:01:45.500','4000-essential-english-words-1-12'),
	('But after some time, many people began to like his painting','Nhưng sau một lúc, nhiều người bắt đầu thích tranh của anh ấy','00:01:45.500','00:01:49.500','4000-essential-english-words-1-12'),
	('People wrote articles about it in magazines','Mọi người viết bài báo về nó trên tạp chí','00:01:49.500','00:01:52.500','4000-essential-english-words-1-12'),
	('They said it was his best work','Họ nói đó là tác phẩm hay nhất của anh ấy','00:01:52.500','00:01:54.400','4000-essential-english-words-1-12'),
	('They loved his strange symbols','Họ yêu thích những biểu tượng kỳ lạ của anh','00:01:54.400','00:01:56.800','4000-essential-english-words-1-12'),
	('They loved his strange colors','Họ yêu thích những màu sắc kỳ lạ của anh','00:01:56.800','00:01:58.700','4000-essential-english-words-1-12'),
	('Frenhofer\'s painting reminded everyone that just because something was new didn\'t mean that it was bad','Bức tranh của Frenhofer nhắc nhở mọi người rằng chỉ vì một thứ gì đó mới mẻ thì không có nghĩa là nó tồi tệ','00:01:58.700','00:02:04.900','4000-essential-english-words-1-12'),
	('He also helped them to realize that sometimes it takes people a little time to understand great things','Anh cũng giúp họ nhận ra rằng đôi khi cần một chút thời gian để mọi người hiểu những điều tuyệt vời','00:02:04.900','00:02:11.500','4000-essential-english-words-1-12'),

	/* (UUID(),'4000-essential-english-words-1-13','The farmer and the cats','Người nông dân và những con mèo','4000_ESSENTIAL_ENGLISH_WORDS_1_13.mp3',NULL,'00:00:00.000','00:02:03.600','4000-essential-english-words-1',0,0,13) */
	('The farmer and the cats','Người nông dân và những con mèo','00:00:00.960','00:00:03.500','4000-essential-english-words-1-13'),
	('Arthur was a responsible farmer, and Maria was a nice lady','Arthur là một người nông dân có trách nhiệm, và Maria là một người phụ nữ tốt bụng','00:00:03.600','00:00:09.000','4000-essential-english-words-1-13'),
	('But they were poor','Nhưng họ nghèo lắm','00:00:09.000','00:00:10.570','4000-essential-english-words-1-13'),
	('They owed the town lord money for their land','Họ nợ lãnh chúa thị trấn tiền đất','00:00:10.600','00:00:13.600','4000-essential-english-words-1-13'),
	('One summer, their farm burned','Một mùa hè nọ, trang trại của họ bị thiêu rụi','00:00:13.630','00:00:16.150','4000-essential-english-words-1-13'),
	('One structure caught fire, and most of the animals ran away',' Một công trình bị bốc cháy, và hầu hết các con vật đều bỏ chạy','00:00:16.250','00:00:20.800','4000-essential-english-words-1-13'),
	('Only the cats stayed','Chỉ có đàn mèo ở lại','00:00:20.800','00:00:22.700','4000-essential-english-words-1-13'),
	('So Arthur and Maria had to bring in their crops without an animal\'s help','Vậy là Arthur và Maria phải thu hoạch nông sản của họ mà không có sự giúp đỡ của các con vật','00:00:22.700','00:00:27.800','4000-essential-english-words-1-13'),
	('On a fall day, the lord demanded his money','Vào một ngày mùa thu, lãnh chúa đòi tiền của ông','00:00:27.800','00:00:31.300','4000-essential-english-words-1-13'),
	('Arthur asked if the lord could wait until he brought in his crops','Arthur hỏi liệu lãnh chúa có thể đợi đến khi ông thu hoạch mùa vụ','00:00:31.300','00:00:35.900','4000-essential-english-words-1-13'),
	('The lord was angry','Lãnh chúa trở nên tức giận','00:00:35.900','00:00:37.800','4000-essential-english-words-1-13'),
	('He raised his hands high and yelled, "Pay me by the end of the week"','Ông ta giơ tay cao và hét lên, "Phải trả tiền cho tao vào cuối tuần"','00:00:37.800','00:00:42.400','4000-essential-english-words-1-13'),
	('"If you don\'t, I will increase the money you have to pay"','Còn nếu mày không làm được, tao sẽ tăng số tiền mà mày phải trả lên','00:00:42.400','00:00:46.100','4000-essential-english-words-1-13'),
	('"I might put you in a jail cell"','"Tao có thể tống mày vào một cái phòng giam đấy"','00:00:46.100','00:00:49.100','4000-essential-english-words-1-13'),
	('So Arthur and Maria worked until there was blood on their hands','Thế là Arthur và Maria đã làm việc cho đến khi bàn tay họ đã rướm máu','00:00:49.100','00:00:53.600','4000-essential-english-words-1-13'),
	('They finished four lines of corn and went to bed','Họ xong được bốn hàng cây ngô và lên giường đi ngủ','00:00:53.600','00:00:57.100','4000-essential-english-words-1-13'),
	('But the next morning, eight lines were finished','Nhưng đến sáng hôm sau, tám hàng đã xong','00:00:57.100','00:01:00.600','4000-essential-english-words-1-13'),
	('"Maria, didn\'t we stop in this spot here?" Arthur asked','"Maria, chẳng phải chúng ta dừng ở chỗ này hay sao?" Arthur hỏi','00:01:00.600','00:01:05.200','4000-essential-english-words-1-13'),
	('"Yes, that is correct"','"Phải, đúng vậy mà"','00:01:05.280','00:01:07.250','4000-essential-english-words-1-13'),
	('"And the tools were in a different position, too," Maria said','"Và các cái dụng cụ thì ở vị trí khác nữa kìa," Maria nói ','00:01:07.450','00:01:11.500','4000-essential-english-words-1-13'),
	('They were surprised and happy','Họ rất bất ngờ và vui sướng','00:01:11.600','00:01:14.050','4000-essential-english-words-1-13'),
	('That day, they worked hard and finished five lines','Ngày hôm đó, họ làm việc chăm chỉ và xong được 5 hàng','00:01:14.100','00:01:17.800','4000-essential-english-words-1-13'),
	('But in the morning, ten lines were done','Nhưng vào buổi sáng, có mười hàng đã được làm xong','00:01:17.800','00:01:20.800','4000-essential-english-words-1-13'),
	('Each day they did a lot of work','Mỗi ngày họ làm rất nhiều việc','00:01:20.800','00:01:23.800','4000-essential-english-words-1-13'),
	('Each night, someone else did an equal amount of work','Mỗi đêm, có người đã làm một lượng công việc tương tự','00:01:23.800','00:01:27.800','4000-essential-english-words-1-13'),
	('In a week, the whole field was finished','Trong một tuần, toàn bộ cánh đồng đã hoàn tất','00:01:27.800','00:01:30.800','4000-essential-english-words-1-13'),
	('"Tomorrow I will sell the crops and pay the lord," Arthur said','"Ngày mai anh sẽ đi bán nông sản và trả tiền cho lãnh chúa," Arthur nói','00:01:30.800','00:01:35.400','4000-essential-english-words-1-13'),
	('But that morning, the crops were gone','Nhưng sáng hôm đó, nông sản đã biến mất','00:01:35.400','00:01:37.830','4000-essential-english-words-1-13'),
	('A bag was in the middle of the field','Có một cái túi ở giữa cánh đồng','00:01:37.850','00:01:40.800','4000-essential-english-words-1-13'),
	('It contained money','Nó đựng tiền trong đó','00:01:40.640','00:01:42.400','4000-essential-english-words-1-13'),
	('"Maria, let\'s see who has helped us work"','"Maria, hãy xem ai là người đã giúp chúng ta làm việc nào"','00:01:42.400','00:01:45.800','4000-essential-english-words-1-13'),
	('Through a hole in the wall, they saw a funny sight','Qua một cái lỗ ở trên tường, họ nhìn thấy một cảnh tượng khôi hài','00:01:45.800','00:01:49.300','4000-essential-english-words-1-13'),
	('The cats were dancing in the field and eating corn','Lũ mèo đang nhảy múa trên cánh đồng và đang ăn ngô','00:01:49.300','00:01:53.000','4000-essential-english-words-1-13'),
	('Now Arthur knew what had happened','Giờ thì Arthur biết chuyện gì đã xảy ra','00:01:53.100','00:01:55.800','4000-essential-english-words-1-13'),
	('The cats had worked at night','Đàn mèo đã làm việc vào ban đêm','00:01:55.800','00:01:57.750','4000-essential-english-words-1-13'),
	('After that, Arthur was very nice to his cats and fed them lots of corn','Kể từ đó, Arthur rất tốt với những con mèo của anh và cho chúng ăn rất nhiều ngô','00:01:57.780','00:02:03.600','4000-essential-english-words-1-13'),

	/* (UUID(),'4000-essential-english-words-1-14','A magical book','Cuốn sách phép thuật','4000_ESSENTIAL_ENGLISH_WORDS_1_14.mp3',NULL,'00:00:00.000','00:02:12.000','4000-essential-english-words-1',0,0,14) */
	('A magical book','Cuốn sách phép thuật','00:00:00.960','00:00:03.000','4000-essential-english-words-1-14'),
	('Sarah loved to read','Sarah thích đọc sách','00:00:03.000','00:00:05.100','4000-essential-english-words-1-14'),
	('She read novels and poems','Cô bé đọc tiểu thuyết và thơ','00:00:05.100','00:00:08.000','4000-essential-english-words-1-14'),
	('She loved the beautiful descriptions and phrases','Cô bé yêu thích những đoạn miêu tả và cụm từ lôi cuốn','00:00:08.000','00:00:11.200','4000-essential-english-words-1-14'),
	('She loved reading work from poets and novelists','Cô bé cũng yêu thích đọc những tác phẩm của các nhà thơ và tiểu thuyết gia','00:00:11.200','00:00:15.000','4000-essential-english-words-1-14'),
	('She didn\'t like video games or technology','Cô bé Sarah lại không thích trò chơi điện tử hay công nghệ','00:00:15.000','00:00:18.000','4000-essential-english-words-1-14'),
	('She was on the basketball team, but she didn\'t like sports','Sarah là thành viên của đội bóng rổ, nhưng cô bé lại không thích chơi thể thao','00:00:18.000','00:00:22.600','4000-essential-english-words-1-14'),
	('Her parents made her play basketball','Bố mẹ bắt cô bé chơi bóng rổ','00:00:22.600','00:00:25.100','4000-essential-english-words-1-14'),
	('In fact, Sarah\'s parents made her do many things','Thực ra thì, bố mẹ của Sarah buộc cô bé làm rất nhiều thứ','00:00:25.100','00:00:28.600','4000-essential-english-words-1-14'),
	('But she didn\'t want to do those things','Nhưng cô lại không muốn làm những điều đó','00:00:28.600','00:00:31.600','4000-essential-english-words-1-14'),
	('She just wanted to sit and read all day','Cô bé chỉ muốn ngồi một chỗ và đọc sách cả ngày thôi','00:00:31.600','00:00:34.600','4000-essential-english-words-1-14'),
	('One day, a small book came in the mail','Một ngày nọ, có một cuốn sách nhỏ được gửi đến hộp thư','00:00:34.600','00:00:37.600','4000-essential-english-words-1-14'),
	('It was for Sarah','Nó dành cho Sarah','00:00:37.600','00:00:39.400','4000-essential-english-words-1-14'),
	('The book looked very special','Quyển sách trông rất đặc biệt','00:00:39.400','00:00:41.450','4000-essential-english-words-1-14'),
	('It was printed on sheets of gold','Nó được in bằng những tờ giấy bằng vàng','00:00:41.500','00:00:44.000','4000-essential-english-words-1-14'),
	('Sarah began to read','Sarah bắt đầu đọc','00:00:44.000','00:00:45.800','4000-essential-english-words-1-14'),
	('The outline of the story was simple','Bố cục câu chuyện khá đơn giản','00:00:45.800','00:00:48.500','4000-essential-english-words-1-14'),
	('It was about a magical place','Nó kể về một vùng đất phép thuật','00:00:48.600','00:00:51.500','4000-essential-english-words-1-14'),
	('Strange things happened there','Những điều kỳ lạ đã diễn ra ở đó','00:00:51.500','00:00:53.800','4000-essential-english-words-1-14'),
	('One example from the book was about a boy who could control people','Một ví dụ từ cuốn sách nói về một cậu bé có thể điều khiển người khác','00:00:53.800','00:00:57.800','4000-essential-english-words-1-14'),
	('In one scene, he made his friends tell funny jokes','Trong một khung cảnh, cậu ta đã khiến cho bạn mình phải kể ra những câu chuyện cười hài hước','00:00:57.800','00:01:01.800','4000-essential-english-words-1-14'),
	('Sarah loved the book','Sarah rất thích cuốn sách','00:01:01.800','00:01:03.600','4000-essential-english-words-1-14'),
	('She read it all the time','Cô lúc nào cũng đọc nó','00:01:03.600','00:01:05.560','4000-essential-english-words-1-14'),
	('Then something strange happened','Rồi một chuyện lạ lùng đã xảy ra','00:01:05.560','00:01:07.800','4000-essential-english-words-1-14'),
	('The book gave Sarah a special power','Quyển sách tặng cho Sarah một năng lực đặc biệt','00:01:07.800','00:01:11.200','4000-essential-english-words-1-14'),
	('She could control other people','Cô có thể điều khiển được người khác','00:01:11.200','00:01:13.700','4000-essential-english-words-1-14'),
	('She was like the boy in the book','Cô trở nên giống hệt như cậu bé ở trong sách','00:01:13.700','00:01:16.200','4000-essential-english-words-1-14'),
	('During one exam, she made her friend tell silly jokes','Trong suốt buổi kiểm tra, cô khiến cho bạn mình phải kể những câu chuyện đùa ngớ ngẩn','00:01:16.200','00:01:20.500','4000-essential-english-words-1-14'),
	('Her friend got in trouble','Bạn bè của cô gặp rắc rối','00:01:20.500','00:01:22.400','4000-essential-english-words-1-14'),
	('After school, Sarah did not make a direct trip home','Tan học, Sarah không đi thẳng về nhà','00:01:22.400','00:01:26.200','4000-essential-english-words-1-14'),
	('On the way, she went to the local store','Trên đường đi, cô ấy đã đến một cửa hàng trong vùng','00:01:26.200','00:01:29.200','4000-essential-english-words-1-14'),
	('She wanted to play more tricks on people','Cô muốn chơi khăm mọi người','00:01:29.200','00:01:31.700','4000-essential-english-words-1-14'),
	('She caused problems','Cô đã gây ra rất nhiều rắc rối','00:01:31.700','00:01:33.600','4000-essential-english-words-1-14'),
	('She made people fall down','Cô làm cho mọi người bị trượt ngã','00:01:33.900','00:01:35.900','4000-essential-english-words-1-14'),
	('She laughed and had fun','Cô bật cười và rất vui vẻ','00:01:35.900','00:01:38.200','4000-essential-english-words-1-14'),
	('Finally she left and started to walk home','Cuối cùng, Sarah rời khỏi đó và bắt đầu đi bộ về nhà','00:01:38.200','00:01:41.500','4000-essential-english-words-1-14'),
	('Then she saw something','Rồi cô nhìn thấy cái gì đó','00:01:41.500','00:01:43.300','4000-essential-english-words-1-14'),
	('Her basketball coach was about to walk in front of a bus','Huấn luyện viên bóng rổ của cô sắp đi tới phía trước một cái xe buýt','00:01:43.300','00:01:47.200','4000-essential-english-words-1-14'),
	('He was looking the other way','Ông ấy đang nhìn sang hướng khác','00:01:47.200','00:01:49.000','4000-essential-english-words-1-14'),
	('She had to stop him','Cô phải ngăn ông lại','00:01:49.000','00:01:50.800','4000-essential-english-words-1-14'),
	('She used her power','Cô sử dụng năng lực của mình','00:01:50.800','00:01:52.800','4000-essential-english-words-1-14'),
	('She controlled him','Cô đã kiểm soát được ông','00:01:52.800','00:01:54.800','4000-essential-english-words-1-14'),
	('She made him stop walking','Cô khiến cho ông dừng bước','00:01:54.800','00:01:56.800','4000-essential-english-words-1-14'),
	('Sarah learned something that day','Sarah đã học được một điều vào ngày hôm đó','00:01:56.800','00:01:59.300','4000-essential-english-words-1-14'),
	('It was better to help people than make them suffer','Giúp đỡ người khác sẽ tốt hơn là việc khiến họ bị tổn thương','00:01:59.300','00:02:02.800','4000-essential-english-words-1-14'),
	('So, she put a limit on how she used her power','Vì thế, cô bé đặt ra giới hạn cho việc cô dùng sức mạnh của mình','00:02:02.800','00:02:05.800','4000-essential-english-words-1-14'),
	('She did not want to do bad things with it anymore','Cô bé không muốn làm những điều xấu với nó nữa','00:02:05.800','00:02:09.200','4000-essential-english-words-1-14'),
	('She only wanted to do good','Cô chỉ muốn làm những điều tốt mà thôi','00:02:09.200','00:02:12.000','4000-essential-english-words-1-14'),

	/* (UUID(),'4000-essential-english-words-1-15','The big race','Cuộc đua lớn','4000_ESSENTIAL_ENGLISH_WORDS_1_15.mp3',NULL,'00:00:00.000','00:02:07.000','4000-essential-english-words-1',0,0,15) */
	('The big race','Cuộc đua lớn','00:00:00.960','00:00:03.000','4000-essential-english-words-1-15'),
	('A dog saw a group of animals across the road','Một chú chó nhìn thấy một nhóm các loài vật ở bên kia đường','00:00:03.000','00:00:06.500','4000-essential-english-words-1-15'),
	('He walked over to meet them','Chú bèn tiến lại để gặp chúng','00:00:06.600','00:00:08.800','4000-essential-english-words-1-15'),
	('"What are you doing?" he asked them','"Mấy cậu đang làm gì vậy?" chú chó hỏi','00:00:08.800','00:00:11.800','4000-essential-english-words-1-15'),
	('"I just sold them tickets to a race between the rabbit and the turtle," the duck responded','"Tôi vừa mới bán cho họ vé xem cuộc đua giữa thỏ và rùa," chú vịt trả lời','00:00:11.800','00:00:17.800','4000-essential-english-words-1-15'),
	('This news excited the dog','Tin tức này khiến chú chó thích thú','00:00:17.800','00:00:20.300','4000-essential-english-words-1-15'),
	('He felt fortunate that he happened to be there','Chú cảm thấy may mắn vì tình cờ ở đây','00:00:20.300','00:00:23.800','4000-essential-english-words-1-15'),
	('"I don\'t have anything to do today," the dog said','"Hôm nay, tôi chẳng có bất cứ việc gì để làm" chú chó nói','00:00:23.800','00:00:26.800','4000-essential-english-words-1-15'),
	('"I want to buy a ticket, too"','"Tôi cũng muốn mua một vé"','00:00:27.000','00:00:29.300','4000-essential-english-words-1-15'),
	('The dog sat down to observe the race','Chú chó ngồi xuống để theo dõi cuộc đua','00:00:29.300','00:00:32.300','4000-essential-english-words-1-15'),
	('The race would be extreme','Cuộc đua sẽ rất khắc nghiệt','00:00:32.300','00:00:34.100','4000-essential-english-words-1-15'),
	('It would be many kilometers in length','Nó sẽ kéo dài nhiều cây số','00:00:34.200','00:00:37.000','4000-essential-english-words-1-15'),
	('The rabbit and the turtle stood next to each other','Chú thỏ và chú rùa đứng cạnh nhau','00:00:37.000','00:00:40.300','4000-essential-english-words-1-15'),
	('They waited for the race to start','Họ chờ cho cuộc đua bắt đầu','00:00:40.400','00:00:42.820','4000-essential-english-words-1-15'),
	('The dog wondered why the turtle agreed to run against the rabbit','Chú chó thắc mắc tại sao chú rùa lại đồng ý chạy đua với chú thỏ','00:00:42.820','00:00:47.400','4000-essential-english-words-1-15'),
	('Being fast was not a characteristic of turtles','Nhanh nhẹn không phải là một đặc điểm của loài rùa','00:00:47.500','00:00:51.500','4000-essential-english-words-1-15'),
	('The rabbit was going to win easily','Chú thỏ sẽ chiến thắng dễ dàng','00:00:51.500','00:00:54.000','4000-essential-english-words-1-15'),
	('Suddenly, the race began','Đột nhiên, cuộc đua bắt đầu','00:00:54.000','00:00:56.400','4000-essential-english-words-1-15'),
	('The rabbit ran extremely quickly','Chú thỏ chạy cực kỳ nhanh','00:00:56.440','00:00:59.200','4000-essential-english-words-1-15'),
	('The turtle walked slowly','Chú rùa bước đi chậm chạp','00:00:59.200','00:01:01.400','4000-essential-english-words-1-15'),
	('After a minute, the rabbit looked back','Sau một phút, chú thỏ nhìn lại','00:01:01.400','00:01:04.200','4000-essential-english-words-1-15'),
	('He saw that the turtle was far behind him and was breathing quickly because he was so tired','Chú thấy chú rùa còn cách mình rất xa phía sau và đang thở gấp vì nó quá mệt','00:01:04.200','00:01:10.400','4000-essential-english-words-1-15'),
	('The rabbit smiled and slowed to a walk','Chú thỏ mỉm cười và đi chậm lại','00:01:10.400','00:01:13.400','4000-essential-english-words-1-15'),
	('A minute later, the rabbit said, "I\'m winning, so I\'ll take a rest"','Một phút sau, chú thỏ nói, "Ta thắng chắc rồi nên ta nghỉ một lát đã"','00:01:13.400','00:01:18.020','4000-essential-english-words-1-15'),
	('He sat and began to consume some grass','Chú ngồi xuống và bắt đầu ăn vài ngọn cỏ','00:01:18.040','00:01:20.890','4000-essential-english-words-1-15'),
	('Then, he let his eyes close','Rồi chú nhắm mắt lại','00:01:20.920','00:01:22.900','4000-essential-english-words-1-15'),
	('He wasn\'t the winner yet','Chú vẫn chưa phải là người chiến thắng','00:01:23.100','00:01:24.800','4000-essential-english-words-1-15'),
	('But there was no risk of him losing the race',' Nhưng không có bất kỳ nguy cơ nào để chú thua cuộc đua này','00:01:24.800','00:01:28.300','4000-essential-english-words-1-15'),
	('He went to sleep','Chú chìm vào giấc ngủ','00:01:28.300','00:01:29.700','4000-essential-english-words-1-15'),
	('Hours later, a loud sound woke him','Vài giờ sau, một tiếng động lớn đánh thức chú','00:01:29.700','00:01:33.200','4000-essential-english-words-1-15'),
	('All of the animals were yelling and looking at the field','Tất cả mọi con vật đều đang la hét và nhìn về phía cánh đồng','00:01:33.200','00:01:36.950','4000-essential-english-words-1-15'),
	('He felt fear for the first time','Lần đầu tiên trong đời chú cảm thấy sợ hãi','00:01:37.000','00:01:39.600','4000-essential-english-words-1-15'),
	('The turtle was almost at the finish line','Chú Rùa đa gần tới vạch đích','00:01:39.600','00:01:42.600','4000-essential-english-words-1-15'),
	('Now, the rabbit realized his mistake','Đến bây giờ, chú thỏ đã nhận ra sai lầm của mình','00:01:42.600','00:01:45.500','4000-essential-english-words-1-15'),
	('But the race was over','Nhưng cuộc đua đã kết thúc','00:01:45.500','00:01:47.200','4000-essential-english-words-1-15'),
	('He gave the turtle an opportunity to win, and the turtle took it','Chú đã tặng Rùa cơ hội chiến thắng, và Rùa đã nắm lấy cơ hội đó','00:01:47.200','00:01:52.000','4000-essential-english-words-1-15'),
	('The duck handed the turtle his prize','Chú vịt trao giải thưởng cho Rùa','00:01:52.000','00:01:54.490','4000-essential-english-words-1-15'),
	('It was the happiest day of the turtle\'s life','Đó là ngày hạnh phúc nhất trong cuộc đời của Rùa','00:01:54.500','00:01:57.800','4000-essential-english-words-1-15'),
	('The dog was happy for the turtle','Chú chó mừng cho chú rùa','00:01:57.800','00:02:00.270','4000-essential-english-words-1-15'),
	('"He isn\'t fast," the dog thought','"Anh ấy không hề nhanh nhẹn," chú chó nghĩ','00:02:00.300','00:02:02.820','4000-essential-english-words-1-15'),
	('"But he tried his best and did something great"','"Nhưng anh ấy đã cố hết sức mình và làm nên những điều tuyệt vời"','00:02:02.900','00:02:06.870','4000-essential-english-words-1-15');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-1-16','Adams county\'s gold','Vàng ở quận Adams','4000_ESSENTIAL_ENGLISH_WORDS_1_16.mp3',NULL,'00:00:00.000','00:02:11.200','4000-essential-english-words-1',0,0,16) */
	('Adams county\'s gold','Vàng ở quận Adams','00:00:00.960','00:00:03.000','4000-essential-english-words-1-16'),
	('Adams Academy was a good school','Học viện Adams là một trường học tuyệt vời','00:00:03.000','00:00:06.500','4000-essential-english-words-1-16'),
	('Boys lived there and took classes','Các bé trai sống ở đó và tham gia các lớp học','00:00:06.500','00:00:09.500','4000-essential-english-words-1-16'),
	('Tom worked hard all week','Tom đã làm việc chăm chỉ cả tuần','00:00:09.600','00:00:12.000','4000-essential-english-words-1-16'),
	('On a spring Saturday, he wanted to do something fun','Vào một ngày thứ 7 của mùa xuân, cậu bé muốn làm gì đó thật vui','00:00:12.000','00:00:15.800','4000-essential-english-words-1-16'),
	('He asked his friend Jeff to go to the movie theater','Tom rủ bạn cậu, Jeff, đi tới rạp chiếu phim','00:00:15.800','00:00:19.000','4000-essential-english-words-1-16'),
	('"Sorry," Jeff answered','"Xin lỗi cậu," Jeff trả lời','00:00:19.000','00:00:21.300','4000-essential-english-words-1-16'),
	('"I\'m going to a concert"','"Tớ sẽ đi xem hòa nhạc"','00:00:21.300','00:00:23.000','4000-essential-english-words-1-16'),
	('So Tom asked Joe to go to the movies','Nên Tom rủ John đi xem phim','00:00:23.000','00:00:26.000','4000-essential-english-words-1-16'),
	('But Joe\'s soccer team had a game','Nhưng đội bóng đá của Joe có một trận đấu','00:00:26.000','00:00:28.500','4000-essential-english-words-1-16'),
	('Next, Tom went down the hall to Brad\'s room','Sau đó, Tom đi dọc theo sảnh tới phòng Brad','00:00:28.500','00:00:32.500','4000-essential-english-words-1-16'),
	('Brad was reading a very large old book','Brad đang đọc cuốn sách cũ rất to','00:00:32.500','00:00:35.800','4000-essential-english-words-1-16'),
	('"Hi, Brad," Tom said','"Chào Brad," Tom nói','00:00:35.800','00:00:38.300','4000-essential-english-words-1-16'),
	('"Are you reading a dictionary?"','"Cậu đang đọc từ điển à?"','00:00:38.300','00:00:40.200','4000-essential-english-words-1-16'),
	('"It looks ancient"','"Nó trông cổ nhỉ?"','00:00:40.300','00:00:42.200','4000-essential-english-words-1-16'),
	('"No"','"Không"','00:00:42.200','00:00:43.140','4000-essential-english-words-1-16'),
	('"This is called The Wealth of Adams County"','"Nó được gọi là Sự giàu có của thành phố Adams"','00:00:43.200','00:00:46.200','4000-essential-english-words-1-16'),
	('"It\'s about hidden gold in Adams County"','"Nó nói về số vàng bị cất giấu ở thành phố Adams"','00:00:46.200','00:00:49.200','4000-essential-english-words-1-16'),
	('"It\'s more than a century old"','"Nó hơn 100 năm tuổi rồi đó"','00:00:49.200','00:00:51.800','4000-essential-english-words-1-16'),
	('"It was published in 1870"','"Nó được xuất bản năm 1870"','00:00:51.800','00:00:54.500','4000-essential-english-words-1-16'),
	('"Look, it even has the original cover on it"','"Nhìn này, nó thậm chí còn có cả bìa gốc nữa"','00:00:54.500','00:00:58.000','4000-essential-english-words-1-16'),
	('Tom asked, "Where did you get it?"','Tom liền hỏi, "Cậu lấy nó ở đâu thế?"','00:00:58.000','00:01:01.000','4000-essential-english-words-1-16'),
	('"It\'s from my dad\'s friend"','"Từ bạn của bố mình đấy"','00:01:01.000','00:01:03.020','4000-essential-english-words-1-16'),
	('"He is a nice gentleman, an officer in the army," answered Brad','"Chú ấy là một quý ông tốt bụng, một sĩ quan trong quân đội đấy" Brad đáp lại','00:01:03.070','00:01:07.700','4000-essential-english-words-1-16'),
	('"The gold doesn\'t really exist, does it?" Tom asked','"Số vàng đó không thực sự tồn tại, đúng không?" Tom hỏi tiếp','00:01:07.700','00:01:12.800','4000-essential-english-words-1-16'),
	('"I don\'t know, but maybe"','"Tớ không biết, nhưng có thể có"','00:01:12.800','00:01:15.200','4000-essential-english-words-1-16'),
	('"There are clues to it in this book"','"Có những manh mối về nó trong cuốn sách đấy"','00:01:15.200','00:01:17.200','4000-essential-english-words-1-16'),
	('"Let\'s find it"','"Mình thử tìm nhé"','00:01:17.200','00:01:18.800','4000-essential-english-words-1-16'),
	('"Looking for gold sounded like fun"','"Việc tìm vàng nghe có vẻ vui mà"','00:01:18.800','00:01:21.400','4000-essential-english-words-1-16'),
	('The first clue was to find a flat tree underground','Manh mối đầu tiên là việc tìm một cái cây nằm ngang dưới mặt đất','00:01:21.400','00:01:25.200','4000-essential-english-words-1-16'),
	('"It must be in the forest," Tom said','"Nó nhất định là ở trong rừng," Tom nói','00:01:25.200','00:01:28.600','4000-essential-english-words-1-16'),
	('Brad said, "The flat tree could be a board under the dirt"','Brad lại nói, "Cây nằm ngang à, có lẽ là chiếc phản dưới chỗ bùn kia"','00:01:28.650','00:01:33.200','4000-essential-english-words-1-16'),
	('"It could cover the gold"','"Nó có thể che đi chỗ vàng đấy"','00:01:33.200','00:01:35.200','4000-essential-english-words-1-16'),
	('Tom and Brad dug in the dirt all morning','Tom và Brad đào tung chỗ bùn cả buổi sáng','00:01:35.200','00:01:38.500','4000-essential-english-words-1-16'),
	('The process of looking for gold made them hungry','Quá trình tìm vàng khiến họ đói bụng','00:01:38.500','00:01:41.800','4000-essential-english-words-1-16'),
	('They were ready to stop for lunch','Chúng chuẩn bị dừng lại để ăn trưa','00:01:41.800','00:01:44.000','4000-essential-english-words-1-16'),
	('But then Brad hit something hard','Nhưng rồi Brad va phải vật gì đó cứng','00:01:44.000','00:01:46.400','4000-essential-english-words-1-16'),
	('It was a board','Đó là tấm phản','00:01:46.400','00:01:47.800','4000-essential-english-words-1-16'),
	('Brad pounded on the board until it broke','Brad đập mạnh vào tấm phản cho đến khi nó bị vỡ','00:01:47.840','00:01:51.200','4000-essential-english-words-1-16'),
	('There was a small hole under it','Có một chiếc lỗ nhỏ dưới đó','00:01:51.200','00:01:53.600','4000-essential-english-words-1-16'),
	('"Look"','"Nhìn kìa"','00:01:53.600','00:01:54.810','4000-essential-english-words-1-16'),
	('He held up a gold coin','Cậu bé nhặt lên một đồng xu vàng','00:01:54.840','00:01:57.100','4000-essential-english-words-1-16'),
	('Tom saw a piece of paper in the hole','Tom nhìn thấy một mẩu giấy trong lỗ','00:01:57.100','00:02:00.000','4000-essential-english-words-1-16'),
	('"Brad. There\'s more"','"Brad. Còn nữa đấy"','00:02:00.000','00:02:01.840','4000-essential-english-words-1-16'),
	('"It\'s a map to the rest of the gold"','"Đó là bản đồ tới số vàng còn lại"','00:02:01.840','00:02:04.200','4000-essential-english-words-1-16'),
	('Brad smiled','Brad mỉm cười','00:02:04.200','00:02:06.000','4000-essential-english-words-1-16'),
	('"Let\'s go"','"Đi thôi"','00:02:06.000','00:02:07.800','4000-essential-english-words-1-16'),
	('And they hurried to find the wealth of Adams County','Và chúng vội vã đi tìm số tài sản ở quận Adams','00:02:07.800','00:02:11.200','4000-essential-english-words-1-16'),

	/* (UUID(),'4000-essential-english-words-1-17','The race for water','Cuộc đua giành nước','4000_ESSENTIAL_ENGLISH_WORDS_1_17.mp3',NULL,'00:00:00.000','00:02:10.300','4000-essential-english-words-1',0,0,17) */
	('The race for water','Cuộc đua giành nước','00:00:00.960','00:00:03.400','4000-essential-english-words-1-17'),
	('There was a town next to a river','Có một thị trấn nhỏ bên cạnh một dòng sông','00:00:03.400','00:00:06.400','4000-essential-english-words-1-17'),
	('The people there had a lot of water','Mọi người ở đây có rất nhiều nước','00:00:06.400','00:00:09.400','4000-essential-english-words-1-17'),
	('But they wasted it','Nhưng họ lại lãng phí nó','00:00:09.400','00:00:11.300','4000-essential-english-words-1-17'),
	('That made the Sky angry','Điều đó đã làm Trời nổi giận','00:00:11.300','00:00:13.800','4000-essential-english-words-1-17'),
	('It said, "If you waste water, I will take it away from you"','Người nói rằng : "Nếu các người hoang phí nước, ta sẽ lấy nó từ các ngươi"','00:00:13.800','00:00:18.800','4000-essential-english-words-1-17'),
	('But the people didn\'t listen','Nhưng không ai lắng nghe','00:00:18.800','00:00:21.200','4000-essential-english-words-1-17'),
	('When the season changed from spring to summer, the clouds disappeared','Khi thời tiết thay đổi từ mùa xuân sang mùa hạ, những đám mây dần biến mất','00:00:21.200','00:00:26.200','4000-essential-english-words-1-17'),
	('The bright sun was hot and made the river dry','Mặt trời chói chang nóng rực khiến cho dòng sông khô cạn','00:00:26.200','00:00:30.200','4000-essential-english-words-1-17'),
	('There was no water available','Không còn nguồn nước sẵn có nữa','00:00:30.200','00:00:32.600','4000-essential-english-words-1-17'),
	('People asked, "When will the rain fall?"','Mọi người hỏi: "Bao giờ thì mưa sẽ rơi?"','00:00:32.600','00:00:36.150','4000-essential-english-words-1-17'),
	('The Sky\'s response was, "You don\'t appreciate water"','Trời đáp lại rằng : "Các ngươi không trân trọng nước"','00:00:36.200','00:00:40.450','4000-essential-english-words-1-17'),
	('"You waste it, and now I will never make rain again"','"Các ngươi đã hoang phí nó, và giờ ta sẽ không bao giờ làm mưa nữa"','00:00:40.540','00:00:44.800','4000-essential-english-words-1-17'),
	('A boy determined that this wasn\'t fair','Một cậu bé xác nhận rằng điều này không công bằng chút nào','00:00:44.800','00:00:47.800','4000-essential-english-words-1-17'),
	('He thought of a solution','Cậu đã nghĩ ra một cách','00:00:47.800','00:00:49.650','4000-essential-english-words-1-17'),
	('He asked the Sky to race him','Cậu bé yêu cầu Trời hãy chạy thi với mình','00:00:49.650','00:00:51.800','4000-essential-english-words-1-17'),
	('He said, "If I get to the top of that hill before your rain can form puddles, you must fill our river"','Cậu bé nói : "Nếu tôi tới đỉnh đồi đó trước khi mưa của ông có thể tạo thành những vũng nước, thì ông phải cho đầy nước xuống dòng sông của chúng tôi"','00:00:51.800','00:00:59.600','4000-essential-english-words-1-17'),
	('The Sky laughed','Trời bật cười','00:00:59.600','00:01:01.020','4000-essential-english-words-1-17'),
	('"Little boy, I am the Sky"','"Này cậu bé, ta là Trời"','00:01:01.080','00:01:03.520','4000-essential-english-words-1-17'),
	('"I am above everything else"','"Ta ở trên tất cả mọi thứ khác"','00:01:03.560','00:01:05.760','4000-essential-english-words-1-17'),
	('"You cannot beat me"','"Ngươi không thể đánh bại được ta đâu"','00:01:05.800','00:01:07.800','4000-essential-english-words-1-17'),
	('But the boy knew he would win','Nhưng cậu bé biết chắc mình sẽ thắng','00:01:07.800','00:01:10.300','4000-essential-english-words-1-17'),
	('When the race began, the boy ran forward','Khi cuộc đua bắt đầu, cậu bé chạy về phía trước','00:01:10.300','00:01:13.800','4000-essential-english-words-1-17'),
	('The Sky started raining on the hill','Trời bắt đầu đổ mưa lên ngọn đồi','00:01:13.800','00:01:16.070','4000-essential-english-words-1-17'),
	('But puddles did not form there','Thế nhưng những vũng nước không thể hình thành ở đó được','00:01:16.200','00:01:18.400','4000-essential-english-words-1-17'),
	('When it rained on the hill, the water went down','Khi mưa ở đồi, nước cứ thế chảy xuống','00:01:18.450','00:01:21.980','4000-essential-english-words-1-17'),
	('The Sky kept raining','Trời lại tiếp tục mưa','00:01:22.000','00:01:24.200','4000-essential-english-words-1-17'),
	('The water flowed down into the river','Nước chảy xuống dòng sông','00:01:24.300','00:01:26.950','4000-essential-english-words-1-17'),
	('When the boy reached the top of the hill, the river was full','Khi cậu bé tới đỉnh đồi, nước ở sông đã đầy','00:01:26.970','00:01:31.350','4000-essential-english-words-1-17'),
	('The people began to celebrate','Người dân bắt đầu ăn mừng','00:01:31.360','00:01:33.800','4000-essential-english-words-1-17'),
	('It was the highest level the river had ever been at before','Đây là mức nước cao nhất mà dòng sông từng có trước đây','00:01:33.800','00:01:38.300','4000-essential-english-words-1-17'),
	('The Sky was angry','Trời nổi giận','00:01:38.300','00:01:40.100','4000-essential-english-words-1-17'),
	('"A boy can\'t beat me"','"Cậu bé không thể thắng được ta"','00:01:40.100','00:01:42.000','4000-essential-english-words-1-17'),
	('"I won\'t fill your river," it said','"Ta sẽ không lấp đầy dòng sông của các ngươi," trời nói','00:01:42.060','00:01:45.000','4000-essential-english-words-1-17'),
	('Now the boy laughed','Giờ thì cậu bé bật cười','00:01:45.120','00:01:46.800','4000-essential-english-words-1-17'),
	('"It doesn\'t matter whether you want to fill it or not," he said','"Điều đó không quan trọng là dù Ngài có muốn lấp đầy dòng sông hay không," cậu bé nói','00:01:46.800','00:01:50.920','4000-essential-english-words-1-17'),
	('"You already did"','"Ngài đã làm nó rồi"','00:01:51.100','00:01:52.570','4000-essential-english-words-1-17'),
	('The Sky looked at the full river','Trời nhìn thấy dòng sông tràn đầy nước','00:01:52.610','00:01:55.100','4000-essential-english-words-1-17'),
	('"You tricked me," it said','"Ngươi đã lừa ta," trời nói','00:01:55.100','00:01:57.400','4000-essential-english-words-1-17'),
	('It asked the people, "Do you appreciate water now?"','Ngài hỏi người dân: "Các người giờ sẽ trân trọng nước chứ?"','00:01:57.450','00:02:01.400','4000-essential-english-words-1-17'),
	('"Yes," they said','"Vâng," họ nói','00:02:01.400','00:02:03.400','4000-essential-english-words-1-17'),
	('"We won\'t waste it"','"Chúng tôi sẽ không phí phạm nó nữa"','00:02:03.400','00:02:04.850','4000-essential-english-words-1-17'),
	('That is how a lone boy saved his town and won the race for water','Đó là cách cậu bé đơn độc cứu thị trấn của mình và giành chiến thắng trong cuộc đua giành nước','00:02:04.900','00:02:10.300','4000-essential-english-words-1-17'),

	/* (UUID(),'4000-essential-english-words-1-18','The little red chicken','Cô gà đỏ bé nhỏ','4000_ESSENTIAL_ENGLISH_WORDS_1_18.mp3',NULL,'00:00:00.000','00:01:57.200','4000-essential-english-words-1',0,0,18) */
	('A little red chicken had a store in a small town','Một con gà đỏ bé nhỏ có một cửa hàng trong một thị trấn nhỏ','00:00:02.800','00:00:07.300','4000-essential-english-words-1-18'),
	('She sold many different items to people in the town','Cô ta bán nhiều sản phẩm khác nhau cho mọi người trong thị trấn','00:00:07.300','00:00:11.300','4000-essential-english-words-1-18'),
	('The people loved her products','Mọi người đều thích những sản phẩm của cô','00:00:11.300','00:00:13.800','4000-essential-english-words-1-18'),
	('One day, a cat came to her property','Một ngày nọ, một chú mèo đã đến nhà của cô','00:00:13.800','00:00:16.800','4000-essential-english-words-1-18'),
	('He saw the sign that indicated where the chicken\'s store was located','Cậu ta thấy một ký hiệu chỉ đường đến nơi cửa hàng của cô gà nằm','00:00:16.800','00:00:21.300','4000-essential-english-words-1-18'),
	('He wanted to purchase bread, but the chicken\'s store was almost empty','Cậu ấy muốn mua bánh mì, nhưng cửa hàng của cô gà hầu như đã trống rỗng','00:00:21.300','00:00:25.800','4000-essential-english-words-1-18'),
	('She had only a bag of wheat','Cô ấy chỉ còn lại một túi lúa mì','00:00:25.800','00:00:28.700','4000-essential-english-words-1-18'),
	('"You can use the wheat to make bread," the chicken said','"Cậu có thể dùng lúa mì để làm bánh mì", cô gà nói','00:00:28.700','00:00:32.800','4000-essential-english-words-1-18'),
	('"No, I don\'t want to work," the cat said','"Không, tôi không muốn làm việc", con mèo nói','00:00:32.800','00:00:36.700','4000-essential-english-words-1-18'),
	('"I just want to buy bread"','"Tôi chỉ muốn mua bánh mì"','00:00:36.700','00:00:38.800','4000-essential-english-words-1-18'),
	('The cat became angry and left the store','Con mèo giận dữ và rời khỏi cửa hàng','00:00:38.800','00:00:42.200','4000-essential-english-words-1-18'),
	('Later, the little red chicken saw the cat in a crowd','Lát sau, cô gà đỏ bé nhỏ đã thấy chú mèo trong đám đông','00:00:42.200','00:00:46.800','4000-essential-english-words-1-18'),
	('"I will help you make the bread," she said','"Tôi sẽ giúp cậu làm bánh mì", cô ấy nói','00:00:46.800','00:00:50.300','4000-essential-english-words-1-18'),
	('But the cat treated her badly','Nhưng chú mèo đối xử với cô ấy rất tệ','00:00:50.300','00:00:52.800','4000-essential-english-words-1-18'),
	('He did not even communicate with her','Cậu ấy thậm chí còn không nói chuyện với cô','00:00:52.800','00:00:55.300','4000-essential-english-words-1-18'),
	('He did not want to do any work','Cậu ấy không muốn làm bất cứ việc gì','00:00:55.300','00:00:57.800','4000-essential-english-words-1-18'),
	('So the chicken decided to make the bread','Vì thế cô gà đã quyết định làm chiếc bánh mì','00:00:57.800','00:01:00.700','4000-essential-english-words-1-18'),
	('She selected the exact amount of wheat to make fresh bread','Cô chọn chính xác lượng lúa mì để làm bánh mì tươi','00:01:00.700','00:01:04.700','4000-essential-english-words-1-18'),
	('She used a stone to pound the wheat to get it ready','Cô dùng một hòn đá nghiền nhỏ lúa mì để chuẩn bị','00:01:04.700','00:01:08.400','4000-essential-english-words-1-18'),
	('Soon, her bread was ready','Chẳng bao lâu sau, bánh mì của cô ấy đã chuẩn bị sẵn sàng','00:01:08.400','00:01:11.200','4000-essential-english-words-1-18'),
	('The cat came and saw the bread on a dish','Chú mèo đến và thấy chiếc bánh mì ở trong đĩa','00:01:11.200','00:01:14.400','4000-essential-english-words-1-18'),
	('"Give me some of your bread," he said','"Hãy cho tôi một ít bánh mì," anh ấy nói','00:01:14.500','00:01:17.800','4000-essential-english-words-1-18'),
	('"No," said the little red chicken','"Không được," cô gà đỏ bé nhỏ nói','00:01:17.800','00:01:20.800','4000-essential-english-words-1-18'),
	('"You did not help me make the bread"','"Cậu đã không giúp tôi làm bánh mì"','00:01:20.800','00:01:23.200','4000-essential-english-words-1-18'),
	('"So you shall not have any to eat"','"Vì thế cậu sẽ chẳng có gì để ăn cả"','00:01:23.200','00:01:25.400','4000-essential-english-words-1-18'),
	('The cat argued with the chicken','Chú mèo tranh cãi với cô gà','00:01:25.400','00:01:27.800','4000-essential-english-words-1-18'),
	('He tried to offer a price for it','Cậu ấy đã cố gắng đề nghị một mức giá cho chiếc bánh','00:01:27.800','00:01:29.800','4000-essential-english-words-1-18'),
	('But the little red chicken did not want to sell her bread','Nhưng cô gà đỏ nhỏ bé không muốn bán chiếc bánh mì của cô','00:01:29.800','00:01:33.300','4000-essential-english-words-1-18'),
	('"Don\'t depend on others to do work for you," said the little red chicken','"Đừng dựa dẫm vào người khác làm việc cho cậu," cô gà đỏ bé nhỏ nói','00:01:33.300','00:01:38.800','4000-essential-english-words-1-18'),
	('"Then how will I get bread?" the cat asked','"Vậy làm sao để tôi nhận được chiếc bánh mì?" chú mèo hỏi','00:01:38.800','00:01:42.800','4000-essential-english-words-1-18'),
	('"I recommend doing some work," said the little red chicken','"Tôi khuyên cậu nên làm một vài việc," cô gà đỏ bé nhỏ nói','00:01:42.800','00:01:46.800','4000-essential-english-words-1-18'),
	('"Use a tool to plant your own wheat"','"Dùng một dụng cụ để trồng lúa mì của chính cậu"','00:01:46.800','00:01:49.100','4000-essential-english-words-1-18'),
	('"When it grows big, you can gather it and make your own bread"','"Khi chúng lớn lên, cậu có thể thu hoạch chúng và làm bánh mì của riêng mình"','00:01:49.100','00:01:53.100','4000-essential-english-words-1-18'),
	('"You need to learn to do work for what you want"','"Cậu cần học cách làm việc cho những gì cậu muốn"','00:01:53.100','00:01:57.200','4000-essential-english-words-1-18'),

	/* (UUID(),'4000-essential-english-words-1-19','Shipwrecked','Đắm tàu','4000_ESSENTIAL_ENGLISH_WORDS_1_19.mp3',NULL,'00:00:00.000','00:02:14.800','4000-essential-english-words-1',0,0,19) */
	('Shipwrecked','Đắm tàu','00:00:00.960','00:00:02.900','4000-essential-english-words-1-19'),
	('Simon Yates was a lawyer','Simon Yates là một luật sư','00:00:02.900','00:00:05.000','4000-essential-english-words-1-19'),
	('He helped many people','Ông ta giúp đỡ rất nhiều người','00:00:05.300','00:00:06.930','4000-essential-english-words-1-19'),
	('However, he was not a nice man','Tuy nhiên, ông ta không phải là một người tốt','00:00:07.000','00:00:10.000','4000-essential-english-words-1-19'),
	('His policy was to help only rich people','Chính sách của ông ta là chỉ giúp những người giàu có','00:00:10.000','00:00:14.000','4000-essential-english-words-1-19'),
	('He didn\'t bother about social injustice','Ông chẳng thèm bận tâm đến sự bất công xã hội','00:00:14.000','00:00:17.000','4000-essential-english-words-1-19'),
	('He made a lot of money, but many people didn\'t like him','Ông kiếm được rất nhiều tiền, nhưng mọi người chẳng ưa gì ông ta cả','00:00:17.000','00:00:21.800','4000-essential-english-words-1-19'),
	('Even people on his staff didn\'t like him','Ngay cả những người trong số nhân viên của ông ta cũng không hề ưa ông chút nào','00:00:21.800','00:00:25.200','4000-essential-english-words-1-19'),
	('They wanted bad things to happen to him','Họ chỉ mong những điều tồi tệ sẽ xảy đến với ông ta mà thôi','00:00:25.250','00:00:28.200','4000-essential-english-words-1-19'),
	('In fact, they were glad when he got into trouble','Thật ra, họ đã rất vui mừng khi ông ta gặp rắc rối','00:00:28.220','00:00:32.300','4000-essential-english-words-1-19'),
	('Simon had a very bad day','Simon đã có một ngày cực kỳ tồi tệ','00:00:32.300','00:00:35.200','4000-essential-english-words-1-19'),
	('He did many things wrong and lost his job','Ông ta đã làm nhiều điều sai lầm và mất việc','00:00:35.200','00:00:38.270','4000-essential-english-words-1-19'),
	('Soon, he didn\'t have any money','Không lâu sau, ông ta chẳng còn một xu dính túi','00:00:38.400','00:00:41.400','4000-essential-english-words-1-19'),
	('His wife, Mrs.Yates, began to have doubts about him','Vợ của ông ta, bà Yates, bắt đầu nghi ngờ ông','00:00:41.400','00:00:45.760','4000-essential-english-words-1-19'),
	('Simon wanted to start a new life','Simon muốn bắt đầu một cuộc sống mới','00:00:45.800','00:00:48.320','4000-essential-english-words-1-19'),
	('He planned to leave the country','Ông ta dự định sẽ rời khỏi quê hương','00:00:48.380','00:00:50.600','4000-essential-english-words-1-19'),
	('He mentioned his plan to the captain of a ship','Ông ta bày tỏ ý định này với thuyền trưởng của con tàu','00:00:50.600','00:00:54.000','4000-essential-english-words-1-19'),
	('The captain was exploring the world','Thuyền trưởng đã từng khám phá thế giới','00:00:54.000','00:00:57.000','4000-essential-english-words-1-19'),
	('The captain felt bad for Simon and said, "I will take you to foreign countries"','Thuyền trưởng cảm thấy tội nghiệp cho Simon và nói: "Tôi sẽ đưa cậu tới những quốc gia khác"','00:00:57.000','00:01:03.100','4000-essential-english-words-1-19'),
	('They left the next day','Họ rời đi vào ngày hôm sau','00:01:03.100','00:01:05.400','4000-essential-english-words-1-19'),
	('Near the conclusion of their international trip, the weather turned bad','Khi gần kết thúc chuyến hành trình quốc tế, thời tiết bỗng trở nên tồi tệ','00:01:05.400','00:01:10.800','4000-essential-english-words-1-19'),
	('A wave pushed Simon off the boat','Một cơn sóng đẩy Simon ra khỏi thuyền','00:01:10.800','00:01:13.800','4000-essential-english-words-1-19'),
	('But he was alive','Nhưng ông ta vẫn sống sót','00:01:13.900','00:01:15.600','4000-essential-english-words-1-19'),
	('He swam toward an island','Ông ta bơi về phía một hòn đảo','00:01:15.600','00:01:17.600','4000-essential-english-words-1-19'),
	('After a longtime he got there','Sau một lúc lâu ông ta đã tới đó','00:01:17.800','00:01:20.800','4000-essential-english-words-1-19'),
	('At first he was upset','Ban đầu, ông ta thấy rất buồn bực','00:01:20.800','00:01:23.200','4000-essential-english-words-1-19'),
	('He was lost and alone','Ông ta đã bị lạc và lại còn cô đơn','00:01:23.200','00:01:25.700','4000-essential-english-words-1-19'),
	('"I\'ll never go home again," he thought','"Mình sẽ không bao giờ trở về nhà được nữa", ông ta nghĩ','00:01:25.700','00:01:28.800','4000-essential-english-words-1-19'),
	('He had a lot of problems, but he survived','Simon gặp rất nhiều vấn đề nhưng ông ta vẫn sống sót','00:01:28.800','00:01:32.920','4000-essential-english-words-1-19'),
	('He built a house in a tree','Ông xây một ngôi nhà trên cây','00:01:32.950','00:01:35.350','4000-essential-english-words-1-19'),
	('He lived on a diet of fish','Ông sống bằng chế độ dinh dưỡng từ cá','00:01:35.350','00:01:38.200','4000-essential-english-words-1-19'),
	('He made tools from wood and bones','Ông chế tạo công cụ từ gỗ và xương','00:01:38.200','00:01:40.800','4000-essential-english-words-1-19'),
	('He made a cup to drink rainwater','Ông còn làm một chiếc cốc để uống nước mưa','00:01:40.800','00:01:43.800','4000-essential-english-words-1-19'),
	('Slowly he learned to be happy on the island','Dần dần ông đã học được cách để vui vẻ trên hòn đảo','00:01:43.800','00:01:47.320','4000-essential-english-words-1-19'),
	('He swam every day','Ông bơi lội hàng ngày','00:01:47.400','00:01:49.300','4000-essential-english-words-1-19'),
	('He had trouble sometimes, but he always found a way to fix the problem','Đôi khi ông ấy gặp rắc rối, nhưng ông luôn tìm được cách giải quyết rắc rối','00:01:49.400','00:01:54.500','4000-essential-english-words-1-19'),
	('Life was simple','Cuộc sống thật đơn giản','00:01:54.600','00:01:56.000','4000-essential-english-words-1-19'),
	('He liked it','Ông ta thích điều đó','00:01:56.130','00:01:57.500','4000-essential-english-words-1-19'),
	('Finally, people on a ship saw Simon on the island','Cuối cùng, những người ở trên thuyền cũng thấy Simon trên hòn đảo','00:01:57.500','00:02:01.600','4000-essential-english-words-1-19'),
	('They wanted to take him home','Họ muốn đưa ông về nhà','00:02:01.600','00:02:03.600','4000-essential-english-words-1-19'),
	('But Simon was happy','Nhưng Simon đang rất hạnh phúc','00:02:03.600','00:02:05.420','4000-essential-english-words-1-19'),
	('He gave them a long speech about life','Ông ấy còn tặng họ một bài diễn văn dài về cuộc sống','00:02:05.450','00:02:08.420','4000-essential-english-words-1-19'),
	('He said he wanted to stay','Ông nói ông muốn ở lại','00:02:08.450','00:02:10.500','4000-essential-english-words-1-19'),
	('He liked his new, simple life more than his old life','Ông thích cuộc sống mới, đơn giản này hơn cuộc sống trước kia','00:02:10.600','00:02:14.800','4000-essential-english-words-1-19'),

	/* (UUID(),'4000-essential-english-words-1-20','The seven cities of gold','Bảy thành phố vàng','4000_ESSENTIAL_ENGLISH_WORDS_1_20.mp3',NULL,'00:00:00.000','00:02:05.000','4000-essential-english-words-1',0,0,20) */
	('Many years ago, a Spanish officer named Coronado heard the story of seven great cities','Rất nhiều năm về trước, một sĩ quan Tây Ban Nha tên là Coronado nghe được câu chuyện về bảy thành phố lớn','00:00:03.800','00:00:09.800','4000-essential-english-words-1-20'),
	('"The walls of these cities are made of gold," his friends told him','"Những bức tường của những thành phố này được làm bằng vàng," những người bạn đã nói với anh','00:00:09.800','00:00:13.800','4000-essential-english-words-1-20'),
	('"The people eat meat from golden plates and dress in nice clothes," they said','Họ nói: "Người dân ăn thịt từ những chiếc đĩa bằng vàng và mặc trang phục đẹp"','00:00:13.800','00:00:18.800','4000-essential-english-words-1-20'),
	('They called these cities the Seven Cities of Gold','Họ đã gọi những thành phố này là bảy thành phố vàng','00:00:18.800','00:00:22.000','4000-essential-english-words-1-20'),
	('Were the cities real?','Liệu những thành phố này có thực không?','00:00:22.000','00:00:23.800','4000-essential-english-words-1-20'),
	('Coronado never considered asking his friends','Coronado chưa bao giờ nghĩ đến việc hỏi những người bạn mình','00:00:23.800','00:00:26.800','4000-essential-english-words-1-20'),
	('Coronado thought to himself, "The things in these cities must be worth a lot of money"','Coronado nghĩ thầm, "Những thứ bên trong các thành phố này hẳn là đáng giá rất nhiều tiền"','00:00:26.800','00:00:31.800','4000-essential-english-words-1-20'),
	('So he went to find the Seven Cities of Gold','Nên anh ta đã đi tìm Bảy thành phố vàng đó','00:00:31.800','00:00:34.870','4000-essential-english-words-1-20'),
	('He took along three hundred men, many horses, and extra food','Anh ta dẫn theo ba trăm người đàn ông, rất nhiều ngựa và kèm theo đồ ăn','00:00:34.920','00:00:38.970','4000-essential-english-words-1-20'),
	('They headed west','Họ tiến về phía Tây','00:00:38.980','00:00:40.770','4000-essential-english-words-1-20'),
	('Coronado wanted to achieve his goal very badly','Coronado muốn đạt được mục tiêu của anh ta rất nhiều','00:00:40.780','00:00:44.000','4000-essential-english-words-1-20'),
	('Coronado and his men rode for many days','Coronado và những người đàn ông cưỡi ngựa đi trong nhiều ngày','00:00:44.000','00:00:46.980','4000-essential-english-words-1-20'),
	('Then they saw some cities','Rồi họ nhìn thấy một vài thành phố','00:00:47.000','00:00:49.200','4000-essential-english-words-1-20'),
	('"We found the Seven Cities of Gold," his men yelled, but Coronado wasn\'t happy','"Chúng ta đã tìm thấy Bảy thành phố vàng," những người đàn ông hét lên, nhưng Coronado không thấy vui','00:00:49.200','00:00:55.000','4000-essential-english-words-1-20'),
	('He had a different opinion','Anh ta có một quan điểm khác','00:00:55.000','00:00:56.800','4000-essential-english-words-1-20'),
	('"These can\'t be the Seven Cities of Gold," he said','"Đây không thể là Bảy thành phố vàng," anh ta nói,','00:00:56.800','00:01:00.700','4000-essential-english-words-1-20'),
	('"Look, they\'re made of dirt"','"Nhìn đi, chúng được làm bằng đất"','00:01:00.700','00:01:02.700','4000-essential-english-words-1-20'),
	('Coronado was right','Coronado đã đúng','00:01:02.730','00:01:04.230','4000-essential-english-words-1-20'),
	('The cities weren\'t bright and golden','Những thành phố này không tỏa sáng và bằng vàng','00:01:04.250','00:01:06.700','4000-essential-english-words-1-20'),
	('They were dirty and brown','Chúng trông bẩn và phủ màu nâu','00:01:06.700','00:01:08.430','4000-essential-english-words-1-20'),
	('The people didn\'t eat meat from golden plates','Người dân thì không ăn thịt từ những chiếc đĩa vàng','00:01:08.450','00:01:11.500','4000-essential-english-words-1-20'),
	('They ate vegetables from regular bowls','Họ ăn rau từ những chiếc bát thông thường','00:01:11.500','00:01:14.400','4000-essential-english-words-1-20'),
	('They wore the most basic clothes','Họ mặc những đồ cơ bản nhất','00:01:14.400','00:01:16.800','4000-essential-english-words-1-20'),
	('Coronado regarded the cities as ugly places','Coronado coi những thành phố đó là những nơi xấu xí','00:01:16.800','00:01:20.300','4000-essential-english-words-1-20'),
	('"What happened to the cities of gold?" he thought','"Chuyện gì đã xảy ra với những thành phố vàng vậy?" anh ta nghĩ','00:01:20.300','00:01:23.300','4000-essential-english-words-1-20'),
	('"Did someone destroy them?"','"Có phải ai đó đã phá hủy chúng?"','00:01:23.300','00:01:25.200','4000-essential-english-words-1-20'),
	('"Was there a war?"','"Có phải là một cuộc chiến?"','00:01:25.200','00:01:26.600','4000-essential-english-words-1-20'),
	('"Did someone already come and take the gold?"','"Có ai đó đã tới và lấy toàn bộ vàng?"','00:01:26.600','00:01:29.200','4000-essential-english-words-1-20'),
	('That night, the people of the cities entertained Coronado and his men and served them food','Đêm hôm đó, người dân trong những thành phố chiêu đãi Coronado và người của anh ta và phục vụ họ đồ ăn','00:01:29.200','00:01:34.930','4000-essential-english-words-1-20'),
	('They advised Coronado to go home','Họ khuyên Coronado về nhà','00:01:34.960','00:01:37.800','4000-essential-english-words-1-20'),
	('"There is no gold here," they told him','"Không có vàng ở đây đâu," họ nói với anh ta','00:01:37.800','00:01:40.300','4000-essential-english-words-1-20'),
	('Coronado was angry','Coronado rất tức giận','00:01:40.320','00:01:42.200','4000-essential-english-words-1-20'),
	('Did his friends lie to him?','Có phải bạn bè đã nói dối anh?','00:01:42.200','00:01:44.600','4000-essential-english-words-1-20'),
	('He left the next morning','Anh ta rời đi sáng hôm sau','00:01:44.600','00:01:46.500','4000-essential-english-words-1-20'),
	('He looked back at the cities one more time','Anh nhìn lại những thành phố đó một lần nữa','00:01:46.600','00:01:49.600','4000-essential-english-words-1-20'),
	('The sun reflected light on the dirt houses','Mặt trời phản chiếu ánh sáng lên những ngôi nhà bẩn thỉu đó','00:01:49.600','00:01:52.500','4000-essential-english-words-1-20'),
	('Coronado thought he saw a bit of gold','Coronado nghĩ rằng anh đã nhìn thấy một ít vàng','00:01:52.500','00:01:55.400','4000-essential-english-words-1-20'),
	('Were his friends right after all?','Có phải bạn bè của anh ta cuối cùng cũng đúng không?','00:01:55.400','00:01:57.800','4000-essential-english-words-1-20'),
	('"No," he told himself','"Không," anh ta tự nói với bản thân','00:01:57.800','00:02:00.000','4000-essential-english-words-1-20'),
	('"It\'s just the sun"','"Nó chỉ là do mặt trời thôi"','00:02:00.000','00:02:01.800','4000-essential-english-words-1-20'),
	('Then he turned away and went home','Rồi anh ta quay đi và trở về nhà','00:02:01.800','00:02:04.800','4000-essential-english-words-1-20');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-1-21','Katy','Katy','4000_ESSENTIAL_ENGLISH_WORDS_1_21.mp3',NULL,'00:00:00.000','00:02:02.000','4000-essential-english-words-1',0,0,21) */
	('I first met 8-year-old Katy on a rainy afternoon','Tôi gặp cô bé Katy 8 tuổi lần đầu vào một buổi chiều mưa','00:00:02.800','00:00:06.800','4000-essential-english-words-1-21'),
	('I was a nurse at a hospital','Lúc đấy tôi là một y tá tại một bệnh viện','00:00:06.800','00:00:09.500','4000-essential-english-words-1-21'),
	('The clerk at the desk told me about Katy','Lễ tân tại bàn làm việc đã nói với tôi về Katy','00:00:09.600','00:00:12.800','4000-essential-english-words-1-21'),
	('She was there because she felt a lot of pain','Cô bé ở đó bởi vì cảm thấy quá đau','00:00:12.800','00:00:16.300','4000-essential-english-words-1-21'),
	('The doctors located a problem at the base of her brain','Các bác sĩ xác định được vấn đề nằm đáy não cô bé','00:00:16.300','00:00:20.900','4000-essential-english-words-1-21'),
	('I knew she was special, even before she got better','Tôi biết cô bé rất đặc biệt, kể cả trước khi cô bình phục','00:00:20.900','00:00:24.800','4000-essential-english-words-1-21'),
	('I\'ll always remember Katy as a hero','Tôi sẽ luôn mãi nhớ Katy như một người hùng','00:00:24.800','00:00:27.750','4000-essential-english-words-1-21'),
	('When I entered Katy\'s room, she was not in her bed','Khi tôi vào phòng của Katy, cô bé không ở trên giường của mình','00:00:27.750','00:00:31.800','4000-essential-english-words-1-21'),
	('She was in a chair next to Tommy, a little boy','Cô bé ngồi trên ghế cạnh Tommy','00:00:31.800','00:00:35.700','4000-essential-english-words-1-21'),
	('Though Katy did not feel well, she was playing with Tommy and his toys','Mặc dù Katy cảm thấy không khỏe, cô bé vẫn chơi cùng Tommy và đống đồ chơi của cậu','00:00:35.700','00:00:40.900','4000-essential-english-words-1-21'),
	('It took a lot of effort for her just to sit in the chair','Cô bé đã tốn rất nhiều công sức chỉ để ngồi trên ghế','00:00:40.900','00:00:45.000','4000-essential-english-words-1-21'),
	('But she played with Tommy because it made him happy','Nhưng cô bé vẫn chơi cùng Tommy bởi vì điều đó làm cô bé hạnh phúc','00:00:45.000','00:00:48.900','4000-essential-english-words-1-21'),
	('Katy was always smiling and never appeared to be in pain','Katy luôn luôn tươi cười và dường như chưa từng tỏ ra đau đớn','00:00:48.900','00:00:53.800','4000-essential-english-words-1-21'),
	('She refused to just lie in bed','Cô từ chối việc chỉ nằm mãi trên giường bệnh','00:00:53.800','00:00:56.900','4000-essential-english-words-1-21'),
	('One day, I found her painting a picture','Một ngày nọ, tôi thấy cô bé đang vẽ một bức tranh','00:00:56.900','00:01:00.400','4000-essential-english-words-1-21'),
	('Later, she gave it to one of the older patients','Sau đó, cô bé tặng nó cho một trong những bệnh nhân lớn tuổi','00:01:00.400','00:01:04.700','4000-essential-english-words-1-21'),
	('Another day she went outside to get flowers for another sick little girl','Một ngày khác, cô ấy đi ra ngoài để hái những bông hoa cho cô bé đang bị bệnh khác','00:01:04.700','00:01:10.000','4000-essential-english-words-1-21'),
	('Katy made everyone smile','Katy khiến mọi người buồn cười','00:01:10.000','00:01:12.800','4000-essential-english-words-1-21'),
	('The doctors hurried to fix the problem in Katy\'s brain','Các bác sĩ cũng mau chóng giải quyết được vấn đề trong não của Katy','00:01:12.800','00:01:16.800','4000-essential-english-words-1-21'),
	('The operation was successful','Ca phẫu thuật đã thành công','00:01:16.800','00:01:19.700','4000-essential-english-words-1-21'),
	('The doctors informed the hospital staff of the good news','Các bác sĩ đã thông báo với nhân viên bệnh viện tin tốt','00:01:19.700','00:01:23.800','4000-essential-english-words-1-21'),
	('Katy was fine','Katy đã khỏe','00:01:23.800','00:01:25.290','4000-essential-english-words-1-21'),
	('She soon felt excellent','Cô ấy sẽ sớm cảm thấy tuyệt vời','00:01:25.320','00:01:27.800','4000-essential-english-words-1-21'),
	('She got better and was able to leave the hospital a month later','Katy đã hồi phục và có thể rời khỏi bệnh viện một tháng sau đó','00:01:27.800','00:01:32.800','4000-essential-english-words-1-21'),
	('I have had a long career as a nurse','Tôi đã có một sự nghiệp dài với tư cách là một y tá','00:01:32.800','00:01:36.100','4000-essential-english-words-1-21'),
	('I have met many patients','Tôi đã gặp nhiều bệnh nhân','00:01:36.100','00:01:38.200','4000-essential-english-words-1-21'),
	('However, I have never met another girl like Katy','Tuy nhiên tôi chưa hề gặp cô gái nào như Katy cả','00:01:38.200','00:01:42.100','4000-essential-english-words-1-21'),
	('Even after she got well, she still came to the hospital','Ngay cả sau khi cô ấy bình phục, cô vẫn tiếp tục đến thăm bệnh viện','00:01:42.100','00:01:46.600','4000-essential-english-words-1-21'),
	('She played various games with the young patients','Cô ấy chơi nhiều trò chơi cùng các bệnh nhân trẻ tuổi','00:01:46.600','00:01:50.200','4000-essential-english-words-1-21'),
	('She read many books to the older patients','Cô ấy đọc nhiều loại sách cho các bệnh nhân lớn tuổi','00:01:50.200','00:01:53.260','4000-essential-english-words-1-21'),
	('Katy\'s kind heart helped her get better so quickly','Tấm lòng nhân hậu của Katy đã giúp cô ấy hồi phục rất nhanh','00:01:53.300','00:01:56.920','4000-essential-english-words-1-21'),
	('She is a hero to me and everyone else at the hospital','Cô ấy là một anh hùng đối với tôi và những người khác ở bệnh viện','00:01:56.920','00:02:01.800','4000-essential-english-words-1-21'),

	/* (UUID(),'4000-essential-english-words-1-22','A better reward','Một phần thưởng tuyệt vời hơn','4000_ESSENTIAL_ENGLISH_WORDS_1_22.mp3',NULL,'00:00:00.000','00:02:06.000','4000-essential-english-words-1',0,0,22) */
	('Jenny delivered food for a restaurant','Jenny là giao đồ ăn cho một nhà hàng','00:00:03.000','00:00:05.800','4000-essential-english-words-1-22'),
	('She read the newspaper and said, "Uh oh"','Một ngày, cô ấy đọc báo và thốt lên: "Ồ"','00:00:05.800','00:00:09.100','4000-essential-english-words-1-22'),
	('There was a story about a thief','Đó là câu chuyện về một tên trộm','00:00:09.100','00:00:11.600','4000-essential-english-words-1-22'),
	('He stole food, and no one had seen him','Hắn ta lấy trộm đồ ăn, và chưa một ai nhìn thấy hắn cả','00:00:11.600','00:00:14.800','4000-essential-english-words-1-22'),
	('Even the police couldn\'t catch him','Thậm chí cả cảnh sát cũng chưa bắt được hắn','00:00:14.800','00:00:17.200','4000-essential-english-words-1-22'),
	('Jenny was a little scared','Jenny cảm thấy hơi sợ','00:00:17.200','00:00:19.500','4000-essential-english-words-1-22'),
	('She worked close to that area','Cô làm việc gần khu vực đó','00:00:19.500','00:00:21.800','4000-essential-english-words-1-22'),
	('The newspaper included a message from the police: "If anything strange occurs, call us"','Tờ báo kèm theo một tin nhắn từ cảnh sát: "Nếu điều gì bất thường xảy ra, hãy gọi cho chúng tôi"','00:00:21.800','00:00:27.800','4000-essential-english-words-1-22'),
	('"If you help us catch the thief, you\'ll earn a reward"','"Nếu bạn giúp chúng tôi bắt được tên trộm, bạn sẽ nhận được một phần thưởng"','00:00:27.800','00:00:31.730','4000-essential-english-words-1-22'),
	('Jenny talked to Jim','Jenny nói chuyện với Jim','00:00:31.770','00:00:33.800','4000-essential-english-words-1-22'),
	('He managed the restaurant','Anh ấy quản lý một nhà hàng','00:00:33.800','00:00:36.000','4000-essential-english-words-1-22'),
	('"Do you know about the thief?"','"Anh có biết kẻ trộm không?"','00:00:36.000','00:00:38.000','4000-essential-english-words-1-22'),
	('"Yes," he said','"Có", Jim nói','00:00:38.000','00:00:40.100','4000-essential-english-words-1-22'),
	('"But he steals more than one person can eat"','"Nhưng hắn ta trộm nhiều hơn đồ một người có thể ăn được"','00:00:40.100','00:00:42.800','4000-essential-english-words-1-22'),
	('"And why haven\'t the police stopped him yet?"','"Vậy sao cảnh sát vẫn chưa ngăn hắn ta lại?"','00:00:42.800','00:00:45.100','4000-essential-english-words-1-22'),
	('"It\'s a mystery"','"Đó là một bí ẩn"','00:00:45.100','00:00:46.900','4000-essential-english-words-1-22'),
	('"If you see him, contact the police"','"Nếu cô trông thấy hắn, hãy liên lạc với cảnh sát"','00:00:46.900','00:00:49.700','4000-essential-english-words-1-22'),
	('"Don\'t run after him"','"Đừng đuổi theo hắn"','00:00:49.700','00:00:51.200','4000-essential-english-words-1-22'),
	('Jenny drove to a customer\'s house','Jenny lái xe đến nhà của khách hàng','00:00:51.200','00:00:53.800','4000-essential-english-words-1-22'),
	('She left her car and opened the gate to the house','Cô để ô tô ở ngoài và mở cổng vào nhà','00:00:53.800','00:00:56.800','4000-essential-english-words-1-22'),
	('But then she heard a noise by her car','Nhưng rồi cô nghe thấy có tiếng động gần ô tô của mình','00:00:56.800','00:00:59.150','4000-essential-english-words-1-22'),
	('She yelled, "Thief"','Cô la lên: "Trộm"','00:00:59.150','00:01:01.800','4000-essential-english-words-1-22'),
	('She wasn\'t scared','Cô không thấy sợ chút nào','00:01:01.800','00:01:03.100','4000-essential-english-words-1-22'),
	('She wanted the reward','Cô muốn có phần thưởng','00:01:03.100','00:01:04.900','4000-essential-english-words-1-22'),
	('She did the opposite of what Jim told her to do','Cô làm ngược lại những gì Jim nói mình làm','00:01:04.900','00:01:07.800','4000-essential-english-words-1-22'),
	('"Hey," she yelled','"Này," cô hét to','00:01:07.800','00:01:09.900','4000-essential-english-words-1-22'),
	('"Get back here"','"Quay lại đây"','00:01:09.900','00:01:11.700','4000-essential-english-words-1-22'),
	('She set the food on the ground and ran to her car','Cô đặt đồ ăn xuống đất và chạy lại chiếc xe','00:01:11.700','00:01:14.700','4000-essential-english-words-1-22'),
	('But the thief had already left with the food','Nhưng tên trộm đã rời đi cùng đống đồ ăn','00:01:14.700','00:01:17.400','4000-essential-english-words-1-22'),
	('Jenny followed a noise around the corner','Jenny đi theo tiếng động quanh góc đường','00:01:17.400','00:01:20.100','4000-essential-english-words-1-22'),
	('She was amazed','Cô ngạc nhiên','00:01:20.100','00:01:21.800','4000-essential-english-words-1-22'),
	('She saw a dog and some puppies','Cô thấy một con chó to cùng vài chú cún con','00:01:21.800','00:01:24.800','4000-essential-english-words-1-22'),
	('They were eating her food','Chúng đang ăn số đồ ăn vừa bị trộm','00:01:24.800','00:01:26.800','4000-essential-english-words-1-22'),
	('They looked thin and scared','Chúng trông rất gầy và hoảng sợ','00:01:26.800','00:01:29.000','4000-essential-english-words-1-22'),
	('"The actual thief is just a dog"','"Kẻ trộm thực ra chỉ là một con chó"','00:01:29.000','00:01:31.850','4000-essential-english-words-1-22'),
	('"She\'s feeding her puppies," she said','"Nó đang cho lũ chó con ăn," cô nói','00:01:31.850','00:01:34.800','4000-essential-english-words-1-22'),
	('"That\'s why she steals so much food"','"Thế nên nó mới trộm nhiều đồ ăn như vậy"','00:01:34.800','00:01:37.800','4000-essential-english-words-1-22'),
	('Jenny felt bad','Jenny cảm thấy có lỗi','00:01:37.800','00:01:39.200','4000-essential-english-words-1-22'),
	('She tried to comfort the dogs with another plate of food','Cô cố gắng vỗ về những chú chó bằng một đĩa thức ăn khác','00:01:39.200','00:01:42.800','4000-essential-english-words-1-22'),
	('Then she took them back to the store','Sau đó cô đưa chúng quay lại cửa hàng','00:01:42.800','00:01:44.900','4000-essential-english-words-1-22'),
	('Everyone there took a puppy home','Mỗi người ở đó mang về nhà một chú chó con','00:01:44.900','00:01:47.800','4000-essential-english-words-1-22'),
	('Jenny called the police','Jenny gọi cho cảnh sát','00:01:47.800','00:01:49.800','4000-essential-english-words-1-22'),
	('She told them there was no real thief','Cô nói với họ rằng thật ra không có tên trộm nào cả','00:01:49.800','00:01:52.700','4000-essential-english-words-1-22'),
	('Jenny didn\'t do it to receive the reward anymore','Jenny không làm việc này để nhận phần thưởng nữa','00:01:52.700','00:01:55.900','4000-essential-english-words-1-22'),
	('She said, "It was just a dog"','Cô nói: "Đó chỉ là một con chó thôi"','00:01:55.900','00:01:58.800','4000-essential-english-words-1-22'),
	('"But there\'s no charge for catching this thief" she said','"Nhưng không có thù lao cho việc bắt được tên trộm này cả," cô nói','00:01:58.800','00:02:02.700','4000-essential-english-words-1-22'),
	('"My new dog is a better reward"','"Chú chó mới này là phần thưởng tuyệt vời hơn nhiều"','00:02:02.700','00:02:05.700','4000-essential-english-words-1-22'),

	/* (UUID(),'4000-essential-english-words-1-23','The camp','Lều trại','4000_ESSENTIAL_ENGLISH_WORDS_1_23.mp3',NULL,'00:00:00.000','00:02:05.000','4000-essential-english-words-1',0,0,23) */
	('Stacie wanted to stay at a nice hotel for vacation','Stacie muốn ở một khách sạn thật đẹp trong kỳ nghỉ này','00:00:03.000','00:00:06.900','4000-essential-english-words-1-23'),
	('But her parents sent her to a terrible camp instead','Thế nhưng, thay vào đó bố mẹ cô đã gửi cô đến một trại hè tệ hại','00:00:06.900','00:00:10.800','4000-essential-english-words-1-23'),
	('For breakfast, Stacie liked fresh juice and chocolate milk, but she got water at the camp','Bữa sáng, Stacie thích nước ép trái cây và sữa socola, nhưng cô chỉ được uống nước lọc ở trại hè','00:00:10.800','00:00:17.800','4000-essential-english-words-1-23'),
	('In the afternoon she wanted to write poems, but she had to swim','Buổi chiều, Stacie muốn viết thơ nhưng cô lại phải đi bơi','00:00:17.800','00:00:22.800','4000-essential-english-words-1-23'),
	('The camp was near an airport with loud planes','Trại hè này ở gần một sân bay với những chiếc máy bay ồn ào','00:00:22.800','00:00:26.400','4000-essential-english-words-1-23'),
	('Spiderwebs hung over her bed','Thậm chí còn có mạng nhện trên giường cô bé nữa','00:00:26.500','00:00:29.500','4000-essential-english-words-1-23'),
	('To her, the kids\' average behavior was very bad','Cách hành xử của đám trẻ với cô bé cũng rất tệ','00:00:29.500','00:00:33.500','4000-essential-english-words-1-23'),
	('No girl matched her personality','Chẳng có cô bé nào hợp với tính cách của cô','00:00:33.500','00:00:36.300','4000-essential-english-words-1-23'),
	('She hated it','Cô bé rất ghét trại hè','00:00:36.300','00:00:37.600','4000-essential-english-words-1-23'),
	('One day, they had a class','Một ngày nọ, họ phải tham gia một lớp học','00:00:37.600','00:00:39.800','4000-essential-english-words-1-23'),
	('Mental exercise sounded good to Stacie','Những bài tập rèn luyện tinh thần nghe có vẻ hay với Stacie','00:00:39.800','00:00:42.800','4000-essential-english-words-1-23'),
	('But it was a course on water safety','Nhưng hóa ra nó lại là một khóa đào tạo kỹ năng an toàn dưới nước','00:00:42.800','00:00:45.800','4000-essential-english-words-1-23'),
	('They learned how to be safe passengers on a boat','Họ đã học cách bảo đảm an toàn cho mình khi đi thuyền','00:00:45.800','00:00:49.400','4000-essential-english-words-1-23'),
	('Stacie didn\'t ever plan to go on a boat','Stacie còn chẳng chuẩn bị trước là mình sẽ lên thuyền nữa','00:00:49.400','00:00:52.800','4000-essential-english-words-1-23'),
	('The next day, they played a game','Ngày tiếp theo, họ cùng nhau chơi một trò chơi','00:00:52.800','00:00:54.800','4000-essential-english-words-1-23'),
	('There were a red team and a blue team','Có 2 đội, một đôi xanh và đội còn lại là đội đỏ','00:00:54.800','00:00:58.800','4000-essential-english-words-1-23'),
	('Stacie was on the blue team','Stacie là thành viên của đội xanh','00:00:58.800','00:01:01.800','4000-essential-english-words-1-23'),
	('Each team had to try to remove the other team\'s flag from a pole','Mối đội phải cố gắng giật lấy cờ đang cắm ở trong 1 cái hố của đội kia ','00:01:01.800','00:01:05.800','4000-essential-english-words-1-23'),
	('They also had to use water guns','Họ cũng phải sử dụng súng nước nữa','00:01:05.800','00:01:09.400','4000-essential-english-words-1-23'),
	('"I\'m not much of an athlete," she said','"Tớ không phải người giỏi thể thao đâu" cô bé nói','00:01:09.400','00:01:12.100','4000-essential-english-words-1-23'),
	('But she still had to play','Thế nhưng cô bé vẫn phải chơi','00:01:12.100','00:01:14.600','4000-essential-english-words-1-23'),
	('Stacie took a water gun and looked for somewhere to hide','Stacie cầm một cây súng nước và tìm nơi nào đó để trốn','00:01:14.600','00:01:18.300','4000-essential-english-words-1-23'),
	('A boy said, "Stacie, you advance to the middle"','Một câu bé nói "Stacie, cậu di chuyển đến khu trung tâm nhé"','00:01:18.300','00:01:22.200','4000-essential-english-words-1-23'),
	('"I will go right"','"Tớ sẽ qua cánh phải"','00:01:22.200','00:01:23.600','4000-essential-english-words-1-23'),
	('"Those two will go left"','"Hai bạn kia sẽ qua cánh trái"','00:01:23.600','00:01:25.600','4000-essential-english-words-1-23'),
	('Stacie still didn\'t want to play','Stacie vẫn không muốn chơi','00:01:25.600','00:01:27.800','4000-essential-english-words-1-23'),
	('She walked into the forest and saw a red team player coming','Cô bé đi vào rừng và thấy một thành viên đội đỏ đang tiến tới','00:01:27.800','00:01:32.500','4000-essential-english-words-1-23'),
	('Stacie hid behind a tree and then jumped out and shot the other player','Stacie trốn sau một cái cây, sau đó cô bé nhảy ra và bắn đối thủ của mình','00:01:32.500','00:01:37.600','4000-essential-english-words-1-23'),
	('"This is fun" Stacie thought','"Vui thật đấy" Stacie nghĩ','00:01:37.600','00:01:40.600','4000-essential-english-words-1-23'),
	('Several minutes after advancing further, Stacie saw the red flag','Sau vài phút tiến lên, Stacie đã thấy được chiếc cờ đỏ','00:01:40.600','00:01:44.700','4000-essential-english-words-1-23'),
	('A red team member was watching over it','Có một thành viên đội đỏ đang canh chừng chiếc cờ đó','00:01:44.700','00:01:47.800','4000-essential-english-words-1-23'),
	('She shot him with her water gun','Và cô bé bắn cậu bằng súng nước','00:01:47.800','00:01:50.500','4000-essential-english-words-1-23'),
	('Then she lowered the flag and ran back to her team','Rồi cô bé cầm chiếc cờ xuống và chạy về với đội của mình','00:01:50.500','00:01:53.800','4000-essential-english-words-1-23'),
	('"I got it" she yelled','"Tớ lấy được rồi này" Cô bé hét lên','00:01:53.800','00:01:55.800','4000-essential-english-words-1-23'),
	('The blue team won','Đội xanh đã thắng rồi','00:01:55.800','00:01:57.600','4000-essential-english-words-1-23'),
	('Stacie was the hero','Stacie chính là anh hùng của cả đội','00:01:57.600','00:01:59.700','4000-essential-english-words-1-23'),
	('For the rest of the week, Stacie had fun','Và từ đó cho tới hết tuần, Stacie đã rất vui vẻ','00:01:59.700','00:02:02.700','4000-essential-english-words-1-23'),
	('She even made new friends','Cô bé thậm chí còn kết thêm nhiều bạn mới nữa','00:02:02.700','00:02:05.000','4000-essential-english-words-1-23'),

	/* (UUID(),'4000-essential-english-words-1-24','A strong friendship','Tình bạn mạnh mẽ','4000_ESSENTIAL_ENGLISH_WORDS_1_24.mp3',NULL,'00:00:00.000','00:02:05.600','4000-essential-english-words-1',0,0,24) */
	('Tim was the strongest man in the town','Tim là một chàng trai khỏe mạnh nhất trong thị trấn','00:00:03.000','00:00:06.000','4000-essential-english-words-1-24'),
	('When he played sports, he always won','Khi anh ấy chơi thể thao, anh ấy luôn luôn giành chiến thắng','00:00:06.000','00:00:09.000','4000-essential-english-words-1-24'),
	('He performed and exercised in the public park','Anh ấy biểu diễn và luyện tập ở công viên công cộng','00:00:09.000','00:00:12.800','4000-essential-english-words-1-24'),
	('He did this to show everyone how strong he was','Anh ấy làm điều này để cho mọi người biết anh ta khỏe như thế nào','00:00:12.800','00:00:15.800','4000-essential-english-words-1-24'),
	('Most people liked him, but one man didn\'t','Hầu hết mọi người đều quý anh, nhưng có một người thì không','00:00:15.800','00:00:19.200','4000-essential-english-words-1-24'),
	('His name was Jack','Anh ta tên là Jack','00:00:19.200','00:00:20.800','4000-essential-english-words-1-24'),
	('Jack hated Tim','Jack không thích Tim','00:00:20.800','00:00:22.500','4000-essential-english-words-1-24'),
	('Jack was a movie critic and the smartest man in town','Jack là một nhà phê bình điện ảnh và cũng thông minh nhất thị trấn','00:00:22.500','00:00:26.000','4000-essential-english-words-1-24'),
	('He could solve complex math problems','Anh ta có thể giải quyết những vấn đề toán học phức tạp','00:00:26.000','00:00:28.800','4000-essential-english-words-1-24'),
	('But no one cared','Nhưng không ai biết về điều đó','00:00:28.800','00:00:30.600','4000-essential-english-words-1-24'),
	('Jack wanted to be famous like Tim','Jack muốn được nổi tiếng như Tim','00:00:30.600','00:00:32.900','4000-essential-english-words-1-24'),
	('One day, there was an unusual event','Một ngày nọ, có một việc bất thường xảy đến','00:00:32.900','00:00:36.400','4000-essential-english-words-1-24'),
	('A big storm came suddenly','Một cơn bão lớn đột nhiên xuất hiện','00:00:36.400','00:00:38.800','4000-essential-english-words-1-24'),
	('Snow covered the town','Tuyết che phủ cả thị trấn','00:00:38.800','00:00:40.600','4000-essential-english-words-1-24'),
	('No one could get out','Không ai có thể ra khỏi thị trấn','00:00:40.600','00:00:42.700','4000-essential-english-words-1-24'),
	('They needed food','Họ cần có thức ăn để sống','00:00:42.700','00:00:44.400','4000-essential-english-words-1-24'),
	('The people said, "This is a task for a strong man"','Người dân nói, "Đây là một nhiệm vụ dành cho những người đàn ông khỏe mạnh"','00:00:44.400','00:00:48.700','4000-essential-english-words-1-24'),
	('Tim was under pressure to save them','Tim phải chịu áp lực rằng phải cứu họ','00:00:48.700','00:00:51.000','4000-essential-english-words-1-24'),
	('But Jack wanted to be the hero, so they both went','Nhưng Jack, người luôn muốn trở thành một anh hùng, nên cả hai bọn họ đã đi tìm cùng nhau','00:00:51.000','00:00:54.800','4000-essential-english-words-1-24'),
	('Tim said, "You can\'t help because of your lack of strength"','Tim nói: "Cậu không thể giúp mọi người vì cậu không khỏe mạnh"','00:00:54.800','00:00:59.000','4000-essential-english-words-1-24'),
	('But Jack found some small passages under the snow','Nhưng Jack tìm thấy một vài đường hầm nhỏ dưới tuyết','00:00:59.000','00:01:01.950','4000-essential-english-words-1-24'),
	('One of them led toward another town','Một trong số chúng dẫn đến thị trấn khác','00:01:01.950','00:01:04.800','4000-essential-english-words-1-24'),
	('That town had food','Thị trấn đó có thức ăn','00:01:04.800','00:01:06.800','4000-essential-english-words-1-24'),
	('Because Tim was so big and strong, he almost couldn\'t fit inside','Vì thân hình Tim quá to lớn và vạm vỡ nên anh ấy gần như không thể chui vừa','00:01:06.800','00:01:11.800','4000-essential-english-words-1-24'),
	('They walked until there was a block of ice in their way','Họ đi bộ cho tới khi có một tảng băng lớn trên đường đi','00:01:11.800','00:01:14.800','4000-essential-english-words-1-24'),
	('Jack said, "We can\'t get past it"','Jack nói: "Chúng ta không thể vượt qua chỗ này được"','00:01:14.800','00:01:17.800','4000-essential-english-words-1-24'),
	('"But if you strike it, it might break"','"Bởi vì khi cậu chạm mạnh vào tảng băng, nó có thể sẽ sụp xuống"','00:01:17.800','00:01:19.800','4000-essential-english-words-1-24'),
	('Tim knew that was probable','Tim biết điều đó là có thể xảy ra','00:01:19.800','00:01:21.800','4000-essential-english-words-1-24'),
	('He broke it','Anh ta phá vỡ những tảng băng','00:01:21.800','00:01:23.400','4000-essential-english-words-1-24'),
	('When there were more ice blocks, Tim broke them','Tim vẫn phá vỡ các tảng băng cho dù càng ngày càng nhiều hơn','00:01:23.400','00:01:26.900','4000-essential-english-words-1-24'),
	('That made him tired','Điều này làm anh ấy mệt mỏi','00:01:26.900','00:01:28.700','4000-essential-english-words-1-24'),
	('He couldn\'t walk anymore','Anh ấy không thể đi tiếp được nữa','00:01:28.700','00:01:30.600','4000-essential-english-words-1-24'),
	('Jack said, "Let\'s unite and support each other"','Jack nói, "Chúng ta hãy đoàn kết và hỗ trợ lẫn nhau"','00:01:30.600','00:01:34.200','4000-essential-english-words-1-24'),
	('"I\'ll get the food alone"','"Tôi sẽ đi lấy thức ăn một mình"','00:01:34.200','00:01:36.000','4000-essential-english-words-1-24'),
	('"You rest here"','"Cậu hãy ngồi nghỉ ở đây"','00:01:36.000','00:01:37.800','4000-essential-english-words-1-24'),
	('Jack came back with food','Jack quay lại với thức ăn lấy được','00:01:37.800','00:01:39.600','4000-essential-english-words-1-24'),
	('Tim couldn\'t remember which passage led home','Tim không thể nhớ đường hầm nào dẫn về nhà','00:01:39.600','00:01:42.800','4000-essential-english-words-1-24'),
	('He needed Jack to be his guide','Anh ta cần Jack làm người dẫn đường','00:01:42.800','00:01:45.000 ','4000-essential-english-words-1-24'),
	('The men became friends by working together','Họ trở thành bạn bè từ việc làm chung với nhau','00:01:45.000','00:01:48.000','4000-essential-english-words-1-24'),
	('In town, people saw Jack with the food and cheered','Ở thị trấn, mọi người thấy Jack trở về cùng với thức ăn, họ cùng ăn mừng','00:01:48.000','00:01:51.800','4000-essential-english-words-1-24'),
	('They called Jack a hero','Họ gọi Jack là anh hùng','00:01:51.800','00:01:53.800','4000-essential-english-words-1-24'),
	('But Jack didn\'t care','Nhưng Jack không hề để ý tới điều đó','00:01:53.800','00:01:55.700','4000-essential-english-words-1-24'),
	('He was thinking of something else','Anh đang nghĩ tới điều khác','00:01:55.700','00:01:57.800','4000-essential-english-words-1-24'),
	('He said to Tim, "I thought I was smart, but I learned a new term today: friendship"','Anh ta nói với Tim, "Tôi đã nghĩ mình thật thông minh nhưng hôm nay tôi đã học được một bài học mới: Tình bạn"','00:01:57.800','00:02:05.600','4000-essential-english-words-1-24'),

	/* (UUID(),'4000-essential-english-words-1-25','Joe\'s pond','Ao của Joe','4000_ESSENTIAL_ENGLISH_WORDS_1_25.mp3',NULL,'00:00:00.000','00:02:02.100','4000-essential-english-words-1',0,0,25) */
	('Joe made the world a better place','Joe chung tay xây dựng nên một thế giới tốt đẹp hơn','00:00:03.000','00:00:05.900','4000-essential-english-words-1-25'),
	('He got the idea to do that at school','Cậu đã có ý tưởng thực hiện việc này khi còn đang đi học','00:00:05.900','00:00:08.900','4000-essential-english-words-1-25'),
	('He watched a video there','Cậu đã từng được xem một đoạn phim ngắn lúc đó','00:00:08.900','00:00:11.100','4000-essential-english-words-1-25'),
	('It was about a factory','Nó nói về một nhà máy','00:00:11.100','00:00:13.000','4000-essential-english-words-1-25'),
	('This factory produced a lot of trash and put it in a river','Nhà máy này đã sản sinh ra rất nhiều rác và thải xuống một dòng sông','00:00:13.000','00:00:18.000','4000-essential-english-words-1-25'),
	('The trash and water were a bad mix','Rác và nước sông đã hòa trộn lẫn vào nhau','00:00:18.000','00:00:21.000','4000-essential-english-words-1-25'),
	('People populated the area by the river and drank its water','Số người cư trú ở khu vực gần dòng sông này rất đông và họ đều uống nước được lấy từ đó','00:00:21.000','00:00:25.300','4000-essential-english-words-1-25'),
	('This made them sick','Thói quen này làm cho họ nhiễm bệnh','00:00:25.300','00:00:27.300','4000-essential-english-words-1-25'),
	('Many of them needed medicine and made regular visits to doctors','Rất nhiều người trong số đó phải uống thuốc để điều trị và phải thường xuyên đến thăm khám bác sĩ','00:00:27.300','00:00:31.800','4000-essential-english-words-1-25'),
	('But the video wasn\'t all bad news','Nhưng trong đoạn phim đó, không phải mọi thông tin đều tiêu cực','00:00:31.800','00:00:34.800','4000-essential-english-words-1-25'),
	('It showed ways to pick up trash and why it\'s important to do this','Đoạn phim cũng đưa ra cách để thu lượm rác thải và tầm quan trọng của công việc này','00:00:34.800','00:00:38.800','4000-essential-english-words-1-25'),
	('It said people can make a difference to their environment','Nội dung đưa ra là con người có thể tạo ra thay đổi với môi trường họ đang sinh sống','00:00:38.800','00:00:42.800','4000-essential-english-words-1-25'),
	('The video\'s important features made Joe associate trash with hurting people','Những thông điệp quan trọng trong video đó đã khiến Joe có liên tưởng rằng chính rác thải mới là nguyên nhân gây hại cho sức khỏe con ngườ','00:00:42.800','00:00:47.800','4000-essential-english-words-1-25'),
	('One day Joe walked through a park','Vào một ngày nọ, Joe đang đi bộ trong công viên','00:00:47.800','00:00:50.800','4000-essential-english-words-1-25'),
	('He recognized some of the problems from the video','Cậu nhận ra được một số vấn đề trong đoạn phim là có thật','00:00:50.800','00:00:54.500','4000-essential-english-words-1-25'),
	('One instance of these problems was the trash in the pond','Một trong số đó là việc có rác ở trong ao','00:00:54.500','00:00:58.200','4000-essential-english-words-1-25'),
	('It was full of plastic cups','Cốc nhựa ở khắp nơi','00:01:58.200','00:01:00.200','4000-essential-english-words-1-25'),
	('There was too much trash','Thật quá là nhiều rác','00:01:00.200','00:01:01.900','4000-essential-english-words-1-25'),
	('Joe didn\'t want it to hurt anyone','Joe không muốn ai gặp nguy hiểm cả','00:01:01.900','00:01:04.900','4000-essential-english-words-1-25'),
	('He told his grandfather about the park','Cậu đã nói với ông nội mình về cái công viên đầy rác đó','00:01:04.900','00:01:07.900','4000-essential-english-words-1-25'),
	('His grandfather said, "You know, it\'s a tradition in our family to help people"','Ông của cậu đã nói với cậu rằng, "Con biết không, truyền thống của gia đình chúng ta là giúp đỡ người khác"','00:01:07.900','00:01:13.400','4000-essential-english-words-1-25'),
	('"That\'s why we give food to poor people"','"Đó là lý do tại sao chúng ta lấy thức ăn để chia cho người nghèo"','00:01:13.400','00:01:16.400','4000-essential-english-words-1-25'),
	('"Maybe you can help people by cleaning the park"','"Có lẽ con có thể giúp đỡ mọi người bằng cách làm vệ sinh công viên đó"','00:01:16.400','00:01:19.800','4000-essential-english-words-1-25'),
	('Cleaning the park would involve hard work','Vệ sinh công viên là một công việc đòi hỏi sự lao động cực nhọc','00:01:19.800','00:01:22.800','4000-essential-english-words-1-25'),
	('Joe decided to organize a group to help him','Joe quyết định thành lập một nhóm để cùng chung tay hành động với cậu','00:01:22.800','00:01:26.400','4000-essential-english-words-1-25'),
	('He chose a wide area of the park','Cậu chọn ra một khu vực rộng rãi trong công viên','00:01:26.400','00:01:28.800','4000-essential-english-words-1-25'),
	('It had the most trash','Đó cũng là nơi chứa nhiều rác nhất','00:01:28.800','00:01:31.200','4000-essential-english-words-1-25'),
	('He asked his family and friends to come','Cậu cũng nhờ gia đình và bạn bè đến hỗ trợ','00:01:31.200','00:01:33.800','4000-essential-english-words-1-25'),
	('On Saturday, he gave everyone a sharp stick','Hôm thứ Bảy, cậu phát cho mỗi người một cây gậy có đầu nhọn','00:01:33.800','00:01:37.700','4000-essential-english-words-1-25'),
	('They wondered why','Mọi người thắc mắc tại sao','00:01:37.700','00:01:39.100','4000-essential-english-words-1-25'),
	('He said, "You use the stick\'s tip to pick up trash"','Joe giải thích rằng, "Mọi người sẽ cần cái đầu gậy này để khều rác đấy"','00:01:39.100','00:01:42.900','4000-essential-english-words-1-25'),
	('"This makes it easier"','"Dùng cái gậy này sẽ dễ làm hơn đấy"','00:01:42.900','00:01:44.900','4000-essential-english-words-1-25'),
	('They worked for six weeks','Họ đã làm việc đó liên tục trong sáu tuần lễ','00:01:44.900','00:01:46.800','4000-essential-english-words-1-25'),
	('Different people helped each time, but Joe was always there','Luôn có những người khác thay phiên nhau đến giúp sức mỗi lần như vậy nhưng Joe lúc nào cũng có mặt tại đó','00:01:46.800','00:01:51.300','4000-essential-english-words-1-25'),
	('In that period of time, Joe saw a range of results','Trong suốt khoảng thời gian đó, Joe đã thấy được một chuỗi các kết quả','00:01:51.300','00:01:55.800','4000-essential-english-words-1-25'),
	('There was no trash in the water','Rác thải dần dần không còn nữa','00:01:55.800','00:01:57.800','4000-essential-english-words-1-25'),
	('People could swim in it','Giờ đây mọi người có thể đi bơi trong hồ được rồi','00:01:57.800','00:01:59.800','4000-essential-english-words-1-25'),
	('Joe knew that was a good sign','Joe biết rằng đó là một tín hiệu tốt','00:01:59.800','00:02:02.100','4000-essential-english-words-1-25'),
	('He was happy because he helped his environment','Cậu cảm thấy hạnh phúc vì đã cải thiện được môi trường sống quanh mình','00:02:02.100','00:02:05.900','4000-essential-english-words-1-25');

